import {
  genesisLocalStorageKey,
  readGenesisLocalStorageItem,
  writeGenesisLocalStorageItem,
} from "@web/lib/genesis-local-storage";
import i18n from "i18next";
import LanguageDetector from "i18next-browser-languagedetector";
import { initReactI18next } from "react-i18next";
import {
  DEFAULT_LOCALE,
  LOCALE_STORAGE_SUFFIX,
  normalizeLocale,
  SUPPORTED_LOCALES,
  type SupportedLocale,
} from "./locales";
import enCommon from "./locales/en/common.json";
import enSessions from "./locales/en/sessions.json";
import enSettings from "./locales/en/settings.json";
import enShell from "./locales/en/shell.json";
import ptBRCommon from "./locales/pt-BR/common.json";
import ptBRSessions from "./locales/pt-BR/sessions.json";
import ptBRSettings from "./locales/pt-BR/settings.json";
import ptBRShell from "./locales/pt-BR/shell.json";
import "./types";

export {
  DEFAULT_LOCALE,
  isSupportedLocale,
  LOCALE_STORAGE_SUFFIX,
  normalizeLocale,
  SUPPORTED_LOCALES,
  type SupportedLocale,
} from "./locales";

const resources = {
  en: {
    common: enCommon,
    sessions: enSessions,
    settings: enSettings,
    shell: enShell,
  },
  "pt-BR": {
    common: ptBRCommon,
    sessions: ptBRSessions,
    settings: ptBRSettings,
    shell: ptBRShell,
  },
} as const;

function applyDocumentLang(locale: string): void {
  if (typeof document === "undefined") return;
  document.documentElement.lang = normalizeLocale(locale);
}

const genesisLocaleDetector = {
  name: "genesisLocalStorage",
  lookup(): string | undefined {
    const stored = readGenesisLocalStorageItem(LOCALE_STORAGE_SUFFIX);
    return stored ?? undefined;
  },
  cacheUserLanguage(lng: string): void {
    writeGenesisLocalStorageItem(LOCALE_STORAGE_SUFFIX, normalizeLocale(lng));
  },
};

const languageDetector = new LanguageDetector();
languageDetector.addDetector(genesisLocaleDetector);

void i18n
  .use(languageDetector)
  .use(initReactI18next)
  .init({
    resources,
    supportedLngs: [...SUPPORTED_LOCALES],
    fallbackLng: DEFAULT_LOCALE,
    defaultNS: "common",
    ns: ["common", "sessions", "settings", "shell"],
    interpolation: {
      escapeValue: false,
    },
    detection: {
      order: ["genesisLocalStorage", "navigator"],
      caches: ["genesisLocalStorage"],
      lookupLocalStorage: genesisLocalStorageKey(LOCALE_STORAGE_SUFFIX),
      convertDetectedLanguage: (lng) => normalizeLocale(lng),
    },
  });

applyDocumentLang(i18n.resolvedLanguage ?? i18n.language ?? DEFAULT_LOCALE);

i18n.on("languageChanged", (lng) => {
  applyDocumentLang(lng);
});

export function getCurrentLocale(): SupportedLocale {
  return normalizeLocale(i18n.resolvedLanguage ?? i18n.language);
}

export async function setAppLocale(locale: SupportedLocale): Promise<void> {
  const next = normalizeLocale(locale);
  writeGenesisLocalStorageItem(LOCALE_STORAGE_SUFFIX, next);
  await i18n.changeLanguage(next);
}

export default i18n;

export const SUPPORTED_LOCALES = ["en", "pt-BR"] as const;

export type SupportedLocale = (typeof SUPPORTED_LOCALES)[number];

export const DEFAULT_LOCALE: SupportedLocale = "en";

export const LOCALE_STORAGE_SUFFIX = "locale";

export function isSupportedLocale(value: string): value is SupportedLocale {
  return (SUPPORTED_LOCALES as readonly string[]).includes(value);
}

/** Map browser / detector codes onto a supported Genesis locale. */
export function normalizeLocale(value: string | null | undefined): SupportedLocale {
  if (!value) return DEFAULT_LOCALE;
  const trimmed = value.trim();
  if (isSupportedLocale(trimmed)) return trimmed;
  const lower = trimmed.toLowerCase();
  if (lower === "pt" || lower.startsWith("pt-")) return "pt-BR";
  if (lower === "en" || lower.startsWith("en-")) return "en";
  return DEFAULT_LOCALE;
}

import type common from "./locales/en/common.json";
import type sessions from "./locales/en/sessions.json";
import type settings from "./locales/en/settings.json";
import type shell from "./locales/en/shell.json";

export type CommonResources = typeof common;
export type SessionsResources = typeof sessions;
export type SettingsResources = typeof settings;
export type ShellResources = typeof shell;

declare module "i18next" {
  interface CustomTypeOptions {
    defaultNS: "common";
    resources: {
      common: CommonResources;
      sessions: SessionsResources;
      settings: SettingsResources;
      shell: ShellResources;
    };
  }
}

import { describe, expect, it } from "vitest";
import { DEFAULT_LOCALE, isSupportedLocale, normalizeLocale } from "./locales";
import enSessions from "./locales/en/sessions.json";
import enSettings from "./locales/en/settings.json";
import ptBRSessions from "./locales/pt-BR/sessions.json";
import ptBRSettings from "./locales/pt-BR/settings.json";

function leafKeys(value: unknown, prefix = ""): string[] {
  if (!value || typeof value !== "object" || Array.isArray(value)) return [prefix];
  return Object.entries(value).flatMap(([key, child]) =>
    leafKeys(child, prefix ? `${prefix}.${key}` : key),
  );
}

describe("normalizeLocale", () => {
  it("keeps supported locales", () => {
    expect(normalizeLocale("en")).toBe("en");
    expect(normalizeLocale("pt-BR")).toBe("pt-BR");
  });

  it("maps Portuguese browser codes to pt-BR", () => {
    expect(normalizeLocale("pt")).toBe("pt-BR");
    expect(normalizeLocale("pt-PT")).toBe("pt-BR");
  });

  it("maps English variants to en", () => {
    expect(normalizeLocale("en-US")).toBe("en");
    expect(normalizeLocale("en-GB")).toBe("en");
  });

  it("falls back to the default locale", () => {
    expect(normalizeLocale(null)).toBe(DEFAULT_LOCALE);
    expect(normalizeLocale("fr")).toBe(DEFAULT_LOCALE);
    expect(isSupportedLocale("fr")).toBe(false);
  });
});

describe("locale resources", () => {
  it("keeps settings keys in parity across locales", () => {
    expect(leafKeys(ptBRSettings).sort()).toEqual(leafKeys(enSettings).sort());
  });

  it("keeps pt-BR keys in parity with English", () => {
    expect(leafKeys(ptBRSessions).sort()).toEqual(leafKeys(enSessions).sort());
  });
});

