import { normalizeLocale, type SupportedLocale, setAppLocale } from "@web/i18n";
import {
  ACTIVITY_DETAIL_OPTIONS,
  MAX_UI_FONT_SIZE_PX,
  MIN_UI_FONT_SIZE_PX,
  REDUCE_MOTION_OPTIONS,
  type ReduceMotionPreference,
  type SessionActivityDetailLevel,
  useAppearancePreferences,
} from "@web/lib/appearance-preferences";
import { Minus, Plus, RotateCcw } from "lucide-react";
import type { ReactNode } from "react";
import { useTranslation } from "react-i18next";
import { useTheme } from "@/components/theme-provider";
import { Button } from "@/components/ui/button";
import { PiiSendSettings } from "./pii-send-settings";
import { SettingsControlRow, SettingsSelectRow } from "./settings-control-row";
import { SettingsSection, SettingsSectionHeader, settingsCardClassName } from "./settings-section";

function SettingsBlock({
  title,
  description,
  children,
}: {
  title: string;
  description: string;
  children: ReactNode;
}) {
  return (
    <div className="space-y-3">
      <div>
        <h3 className="text-sm font-medium">{title}</h3>
        <p className="mt-1 text-xs text-muted-foreground">{description}</p>
      </div>
      <div className={settingsCardClassName}>
        <div className="divide-y divide-border">{children}</div>
      </div>
    </div>
  );
}

function UiFontSizeStepper() {
  const { t } = useTranslation("common");
  const {
    uiFontSizePx,
    defaultUiFontSizePx,
    isUiFontSizeDefault,
    incrementUiFontSize,
    decrementUiFontSize,
    resetUiFontSize,
  } = useAppearancePreferences();

  return (
    <SettingsControlRow
      label={t("appearance.fontSize.label")}
      description={t("appearance.fontSize.description")}
      controlLeading={
        <Button
          type="button"
          variant="ghost"
          size="icon-sm"
          aria-label={t("appearance.fontSize.resetAria")}
          disabled={isUiFontSizeDefault}
          onClick={resetUiFontSize}
          className="size-8 shrink-0 text-muted-foreground"
        >
          <RotateCcw className="size-3.5" />
        </Button>
      }
      control={
        <div className="flex h-8 w-full items-stretch overflow-hidden rounded-lg border border-input bg-input/30">
          <Button
            type="button"
            variant="ghost"
            size="icon-sm"
            aria-label={t("appearance.fontSize.decreaseAria")}
            disabled={uiFontSizePx <= MIN_UI_FONT_SIZE_PX}
            onClick={decrementUiFontSize}
            className="size-8 shrink-0 rounded-none text-muted-foreground hover:bg-muted/60"
          >
            <Minus className="size-3.5" />
          </Button>
          <span className="flex min-w-0 flex-1 items-center justify-center px-1 text-sm tabular-nums">
            {uiFontSizePx}
          </span>
          <Button
            type="button"
            variant="ghost"
            size="icon-sm"
            aria-label={t("appearance.fontSize.increaseAria")}
            disabled={uiFontSizePx >= MAX_UI_FONT_SIZE_PX}
            onClick={incrementUiFontSize}
            className="size-8 shrink-0 rounded-none text-muted-foreground hover:bg-muted/60"
          >
            <Plus className="size-3.5" />
          </Button>
          {!isUiFontSizeDefault ? (
            <span className="sr-only">
              {t("appearance.fontSize.customSrOnly", { defaultPx: defaultUiFontSizePx })}
            </span>
          ) : null}
        </div>
      }
    />
  );
}

const LANGUAGE_OPTIONS: ReadonlyArray<{
  value: SupportedLocale;
  labelKey: "language.en" | "language.ptBR";
}> = [
  { value: "en", labelKey: "language.en" },
  { value: "pt-BR", labelKey: "language.ptBR" },
];

export function AppearanceSettings() {
  const { t, i18n } = useTranslation("common");
  const { theme, setTheme } = useTheme();
  const { reduceMotion, setReduceMotion, activityDetail, setActivityDetail } =
    useAppearancePreferences();
  const locale = normalizeLocale(i18n.resolvedLanguage ?? i18n.language);

  const themeOptions = [
    { value: "light" as const, label: t("appearance.colorMode.light") },
    { value: "dark" as const, label: t("appearance.colorMode.dark") },
    { value: "system" as const, label: t("appearance.colorMode.system") },
  ];

  return (
    <SettingsSection>
      <SettingsSectionHeader
        title={t("appearance.title")}
        description={t("appearance.description")}
      />

      <SettingsBlock
        title={t("appearance.blocks.display.title")}
        description={t("appearance.blocks.display.description")}
      >
        <SettingsSelectRow
          label={t("appearance.colorMode.label")}
          description={t("appearance.colorMode.description")}
          value={theme}
          options={themeOptions}
          onChange={setTheme}
        />
        <SettingsSelectRow<SupportedLocale>
          label={t("language.label")}
          description={t("language.description")}
          value={locale}
          options={LANGUAGE_OPTIONS.map(({ value, labelKey }) => ({
            value,
            label: t(labelKey),
          }))}
          onChange={(next) => {
            void setAppLocale(next);
          }}
        />
        <UiFontSizeStepper />
        <SettingsSelectRow<ReduceMotionPreference>
          label={t("appearance.reduceMotion.label")}
          description={t("appearance.reduceMotion.description")}
          value={reduceMotion}
          options={REDUCE_MOTION_OPTIONS.map(({ value, label }) => ({ value, label }))}
          onChange={setReduceMotion}
        />
      </SettingsBlock>

      <SettingsBlock
        title={t("appearance.blocks.sessions.title")}
        description={t("appearance.blocks.sessions.description")}
      >
        <SettingsSelectRow<SessionActivityDetailLevel>
          label={t("appearance.activityDetail.label")}
          description={t("appearance.activityDetail.description")}
          value={activityDetail}
          options={ACTIVITY_DETAIL_OPTIONS}
          onChange={setActivityDetail}
        />
        <PiiSendSettings />
      </SettingsBlock>
    </SettingsSection>
  );
}

