import json, re
from pathlib import Path
root=Path('genesis/worktrees/i18n-state-audit/apps/web/src/web/i18n/locales')
pat=re.compile(r'{{\s*([^},]+)')
for name in sorted(p.name for p in (root/'en').glob('*.json')):
    en=json.loads((root/'en'/name).read_text())
    pt=json.loads((root/'pt-BR'/name).read_text())
    def leaves(x,p=()):
        out={}
        if isinstance(x,dict):
            for k,v in x.items(): out.update(leaves(v,p+(k,)))
        else: out['.'.join(p)]=x
        return out
    a,b=leaves(en),leaves(pt)
    mismatch=[]; same=[]
    for k in a.keys() & b.keys():
        av,bv=a[k],b[k]
        if isinstance(av,str) and isinstance(bv,str):
            if set(pat.findall(av)) != set(pat.findall(bv)): mismatch.append(k)
            if av == bv: same.append(k)
    print(f'{name}: leaves={len(a)}, placeholder_mismatches={len(mismatch)}, identical_values={len(same)}')
    if mismatch: print('  placeholder keys:', ', '.join(mismatch[:10]))
PY

