const updates = [];
updates.push(await tools.linear_save_issue({ id: "TAC-684", state: "In Progress" }));
const comments = [
  {
    issueId: "TAC-675",
    body: `Implementation resumed after a fresh tracker/branch audit.

Current code reality on \`origin/internationalization\` at \`85e3e5e63\`:
- Present: TAC-676/677 foundation + shell, TAC-678 sessions/chat, TAC-686 website, and the first TAC-682 settings slice.
- Recovery required: TAC-684 was previously pushed as \`ecb15f318\`, but a later shared-branch rewrite omitted that patch. TAC-684 has been reopened while it is restored.
- TAC-679 and TAC-680 had start comments/statuses but no surviving area implementation commits; both are being restarted from the repaired integration branch.
- TAC-681, TAC-683, and TAC-685 remain pending and will follow in isolated area worktrees.

The integration branch is also behind current main and has merge conflicts. Work now starts by merging current \`origin/main\` into the shared line, preserving current behavior, then restoring onboarding before the remaining areas continue. Progress and verification will be posted per child ticket.`
  },
  {
    issueId: "TAC-684",
    body: `Reopened after branch audit: the completed onboarding/auth implementation commit \`ecb15f318\` was present on \`internationalization\` on 2026-07-31, but a later branch rewrite dropped it. The current remote tip has no \`onboarding\` namespace or translated onboarding/auth routes. The patch is recoverable and is being restored onto the reconciled integration branch, followed by typecheck and focused tests.`
  },
  {
    issueId: "TAC-679",
    body: `State correction: the earlier branch-start update did not produce a surviving Collections implementation commit or registered \`collections\` namespace. Work is being restarted from the repaired \`internationalization\` tip; this ticket remains In Progress because implementation is resuming now.`
  },
  {
    issueId: "TAC-680",
    body: `State correction: the surviving local branch only contains inherited website/onboarding commits and no Apps/Builders implementation or registered \`apps\` namespace. Work is being restarted from the repaired \`internationalization\` tip; this ticket remains In Progress because implementation is resuming now.`
  },
  {
    issueId: "TAC-682",
    body: `Audit confirms the first Settings/Connections slice is present on the remote integration branch, including follow-up security localization, but the ticket is correctly still In Progress: much of the user-facing Settings surface remains outside the \`settings\` namespace. Remaining coverage will resume after the integration branch and TAC-684 are repaired.`
  }
];
for (const comment of comments) updates.push(await tools.linear_save_comment(comment));
return updates;

