const ids = ["TAC-681", "TAC-683", "TAC-685"];
const results = [];
for (const id of ids) results.push(await tools.linear_save_issue({ id, state: "In Progress" }));
const bodies = {
  "TAC-681": "Implementation started in an isolated worktree from current `origin/main`. Scope: Teams list/tree/map/workspace/build and setup flows plus Organization hierarchy/domain/director UI, using a typed `teams` namespace for `en` + `pt-BR`. The verified commit will be replayed onto the repaired `internationalization` branch.",
  "TAC-683": "Implementation started in an isolated worktree from current `origin/main`. Scope: capability list/detail/create/workspace/build/selection/outcomes and capability-specific settings, using a typed `capabilities` namespace for `en` + `pt-BR`. The verified commit will be replayed onto the repaired `internationalization` branch.",
  "TAC-685": "Implementation started in an isolated worktree from current `origin/main`. Scope: Presentations, Ads, Files, Agents, Help, Release, and Share chrome, using a typed `misc` namespace for `en` + `pt-BR`. User/model/file content and release-note bodies remain untranslated by design. The verified commit will be replayed onto the repaired `internationalization` branch."
};
for (const id of ids) results.push(await tools.linear_save_comment({ issueId: id, body: bodies[id] }));
return results;

