+function leafTranslations(value: unknown, prefix = ""): Map<string, string> {
+  if (typeof value === "string") return new Map([[prefix, value]]);
+  if (!value || typeof value !== "object" || Array.isArray(value)) {
+    throw new Error(`Invalid translation value at ${prefix || "<root>"}`);
+  }
+  const entries = new Map<string, string>();
+  for (const [key, child] of Object.entries(value)) {
+    const childPrefix = prefix ? `${prefix}.${key}` : key;
+    for (const [childKey, childValue] of leafTranslations(child, childPrefix)) {
+      entries.set(childKey, childValue);
+    }
+  }
+  return entries;
+}
+
+function interpolationNames(value: string): string[] {
+  return [...value.matchAll(/\{\{\s*([^},\s]+)[^}]*\}\}/g)]
+    .map((match) => match[1])
+    .filter((name): name is string => Boolean(name))
+    .sort();
+}
+
+function expectResourceParity(englishResource: unknown, portugueseResource: unknown): void {
+  const english = leafTranslations(englishResource);
+  const portuguese = leafTranslations(portugueseResource);
+  expect([...portuguese.keys()].sort()).toEqual([...english.keys()].sort());
+  for (const [key, englishValue] of english) {
+    expect(interpolationNames(portuguese.get(key) ?? "")).toEqual(
+      interpolationNames(englishValue),
+    );
+  }
 }

