      { find: "@api", replacement: path.resolve(__dirname, "src/api") },
      { find: "@web", replacement: path.resolve(__dirname, "src/web") },
      { find: "@lib", replacement: path.resolve(__dirname, "src/lib") },
      { find: "@", replacement: path.resolve(__dirname, "src") },
    ],
  },
});

