import {
  SelectableOptionCard,
  SelectableOptionCardGroup,
} from "@web/components/settings/selectable-option-card";
import { Loader2 } from "lucide-react";
import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
  type IntegrationDisconnectProgressMode,
  type IntegrationSyncStopMode,
} from "../../../../domain/collection-sync-labels";

export function IntegrationCollectionDataChoice({
  integrationName,
  selectedMode,
  onSelect,
  disabled = false,
  keepDescription,
  deleteDescription,
}: {
  integrationName: string;
  selectedMode: IntegrationSyncStopMode | null;
  onSelect: (mode: IntegrationSyncStopMode) => void;
  disabled?: boolean;
  keepDescription?: string;
  deleteDescription?: string;
}) {
  const { t } = useTranslation("settings");
  return (
    <SelectableOptionCardGroup
      aria-label={t("sync.disconnect.syncedOptionsAria")}
      value={selectedMode ?? ""}
      onValueChange={(value: string) => onSelect(value as IntegrationSyncStopMode)}
      disabled={disabled}
    >
      <SelectableOptionCard
        value="keep_data"
        title={t("sync.disconnect.keepTitle")}
        description={keepDescription ?? t("sync.disconnect.keepDescription", { provider: integrationName })}
        disabled={disabled}
      />
      <SelectableOptionCard
        value="delete_data"
        title={t("sync.disconnect.deleteTitle")}
        description={deleteDescription ?? t("sync.disconnect.deleteDescription")}
        destructive
        disabled={disabled}
      />
    </SelectableOptionCardGroup>
  );
}

export function IntegrationDisconnectDialog({
  integrationName,
  open,
  hasSyncFootprint,
  disconnecting = false,
  disconnectMode = null,
  description,
  keepDescription,
  deleteDescription,
  onOpenChange,
  onConfirm,
}: {
  integrationName: string;
  open: boolean;
  hasSyncFootprint: boolean;
  disconnecting?: boolean;
  disconnectMode?: IntegrationDisconnectProgressMode | null;
  description?: string;
  keepDescription?: string;
  deleteDescription?: string;
  onOpenChange: (open: boolean) => void;
  onConfirm: (mode?: IntegrationSyncStopMode) => void;
}) {
  const { t } = useTranslation("settings");
  const [selectedMode, setSelectedMode] = useState<IntegrationSyncStopMode | null>(null);

  // biome-ignore lint/correctness/useExhaustiveDependencies: intentional stable hook dependencies
  useEffect(() => {
    if (open) {
      setSelectedMode(null);
    }
  }, [open, hasSyncFootprint]);

  const handleConfirm = () => {
    if (hasSyncFootprint) {
      if (!selectedMode) return;
      onConfirm(selectedMode);
      return;
    }
    onConfirm();
  };

  const progressMode = disconnectMode ?? (hasSyncFootprint ? selectedMode : "simple");
  const provider = integrationName.trim() || t("integrationSetup.fallbackProvider");

  return (
    <AlertDialog open={open} onOpenChange={onOpenChange}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>
            {integrationName.trim()
              ? t("sync.disconnect.title", { provider })
              : t("sync.disconnect.fallbackTitle")}
          </AlertDialogTitle>
          <AlertDialogDescription>
            {description
              ? description
              : hasSyncFootprint
                ? t("sync.disconnect.syncDescription", { provider })
                : t("sync.disconnect.simpleDescription", { provider })}
          </AlertDialogDescription>
        </AlertDialogHeader>

        {hasSyncFootprint ? (
          <IntegrationCollectionDataChoice
            integrationName={integrationName}
            selectedMode={selectedMode}
            onSelect={setSelectedMode}
            disabled={disconnecting}
            keepDescription={keepDescription}
            deleteDescription={deleteDescription}
          />
        ) : null}

        {disconnecting && progressMode ? (
          <div className="flex items-start gap-2 rounded-lg border border-border bg-muted/30 px-4 py-3 text-sm leading-6 text-muted-foreground">
            <Loader2 className="mt-0.5 size-4 shrink-0 animate-spin" aria-hidden="true" />
            <p>
              {progressMode === "delete_data"
                ? t("sync.disconnect.progressDelete", { provider })
                : progressMode === "keep_data"
                  ? t("sync.disconnect.progressKeep", { provider })
                  : t("sync.disconnect.progressSimple", { provider })}
            </p>
          </div>
        ) : null}

        <AlertDialogFooter>
          <AlertDialogCancel disabled={disconnecting}>{t("actions.cancel")}</AlertDialogCancel>
          <AlertDialogAction
            // Simple (non-sync) disconnects are always destructive. Sync keep_data
            // stays default; delete_data is destructive.
            variant={
              !hasSyncFootprint || selectedMode === "delete_data" ? "destructive" : "default"
            }
            disabled={disconnecting || (hasSyncFootprint && selectedMode == null)}
            onClick={handleConfirm}
          >
            {disconnecting ? <Loader2 className="size-4 animate-spin" aria-hidden="true" /> : null}
            {t("actions.disconnect")}
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}

