import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, test } from "vitest";
import { MessageActionBar } from "./message-action-bar";

describe("MessageActionBar", () => {
  test("orders assistant actions before the timestamp", () => {
    const html = renderToStaticMarkup(
      <MessageActionBar
        content="Response"
        timestamp={Date.now()}
        feedbackTargetId="assistant-seq:1"
        showFeedback
      />,
    );

    const copy = html.indexOf("Copy message");
    const up = html.indexOf("Mark response helpful");
    const down = html.indexOf("Mark response not helpful");
    expect(copy).toBeGreaterThan(-1);
    expect(up).toBeGreaterThan(copy);
    expect(down).toBeGreaterThan(up);
    expect(html).toContain("group-hover/response:opacity-100");
  });

  test("keeps user actions to copy and timestamp", () => {
    const html = renderToStaticMarkup(<MessageActionBar content="Prompt" timestamp={Date.now()} />);
    expect(html).toContain("Copy message");
    expect(html).not.toContain("Mark response helpful");
    expect(html).not.toContain("Mark response not helpful");
    expect(html).not.toContain("New thread from here");
  });

  test("omits fork when the thread-fork context is inactive", () => {
    const html = renderToStaticMarkup(
      <MessageActionBar
        content="Response"
        timestamp={Date.now()}
