import { resolvePiiCopyText } from "@lib/pii/client";
import { MessageAction, MessageActions } from "@web/components/ai-elements/message";
import { SessionMessageFeedbackDialog } from "@web/components/session-chat/session-message-feedback-dialog";
import { useSessionThreadFork } from "@web/components/session-chat/session-thread-fork-context";
import { apiFetch } from "@web/lib/api-fetch";
import { formatSessionMessageTimestamp } from "@web/lib/session-message-timestamp";
import { Check, Copy, GitFork, ThumbsDown, ThumbsUp } from "lucide-react";
import { useCallback, useEffect, useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";
import {
  resolveSessionMessageFeedbackTargetId,
  type SessionMessageFeedback,
  type SessionMessageFeedbackRating,
  type SessionMessageFeedbackReason,
} from "../../../domain/session-message-feedback";

export function MessageActionBar({
  content,
  timestamp,
  feedbackTargetId,
  sessionId,
  feedback: initialFeedback,
  showFeedback = false,
  align = "start",
}: {
  content: string;
  timestamp: number;
  feedbackTargetId?: string;
  sessionId?: string;
  feedback?: SessionMessageFeedback;
  showFeedback?: boolean;
  align?: "start" | "end";
}) {
  const { t } = useTranslation("sessions");
  const threadFork = useSessionThreadFork();
  const [copied, setCopied] = useState(false);
  const [feedback, setFeedback] = useState(initialFeedback);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [dialogRating, setDialogRating] = useState<SessionMessageFeedbackRating>(
    initialFeedback?.rating ?? "up",
  );
  const [reasons, setReasons] = useState<SessionMessageFeedbackReason[]>(
    initialFeedback?.reasons ?? [],
  );
  const [detail, setDetail] = useState(initialFeedback?.detail ?? "");
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    setFeedback(initialFeedback);
  }, [initialFeedback]);

  const handleCopy = useCallback(async () => {
    try {
      const text = await resolvePiiCopyText(content, sessionId);
      await navigator.clipboard.writeText(text);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 1000);
    } catch {
      setCopied(false);
    }
  }, [content, sessionId]);

  const saveFeedback = useCallback(
    async (
      rating: SessionMessageFeedbackRating,
      nextReasons: SessionMessageFeedbackReason[],
      nextDetail: string,
    ) => {
      if (!sessionId || !feedbackTargetId) return false;
      const nextFeedback: SessionMessageFeedback = {
        rating,
        reasons: nextReasons,
        detail: nextDetail.trim() || null,
        updatedAt: new Date().toISOString(),
      };
      const previous = feedback;
      setFeedback(nextFeedback);
      setSaving(true);
      try {
        const response = await apiFetch(
          `/api/sessions/${encodeURIComponent(sessionId)}/message-feedback`,
          {
            method: "PUT",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              targetMessageId: feedbackTargetId,
              ...nextFeedback,
            }),
          },
        );
        if (!response.ok) throw new Error("Could not save feedback");
        return true;
      } catch {
        setFeedback(previous);
        toast.error(t("message.feedback.saveError"));
        return false;
      } finally {
        setSaving(false);
      }
    },
    [feedback, feedbackTargetId, sessionId, t],
  );

  const chooseRating = useCallback(
    (rating: SessionMessageFeedbackRating) => {
      const keepDetails = feedback?.rating === rating;
      const nextReasons = keepDetails ? feedback.reasons : [];
      const nextDetail = keepDetails ? (feedback.detail ?? "") : "";
      setDialogRating(rating);
      setReasons(nextReasons);
      setDetail(nextDetail);
      setDialogOpen(true);
      void saveFeedback(rating, nextReasons, nextDetail);
    },
    [feedback, saveFeedback],
  );

  return (
    <MessageActions
      className={[
        "pointer-events-none h-6 opacity-0 transition-opacity duration-150",
        "group-hover/response:pointer-events-auto group-hover/response:opacity-100",
        "group-focus-within/response:pointer-events-auto group-focus-within/response:opacity-100",
        align === "end" ? "justify-end" : "justify-start",
      ].join(" ")}
      aria-label={t("message.actions")}
    >
      <MessageAction
        onClick={() => void handleCopy()}
        tooltip={copied ? t("message.copied") : t("message.copy")}
        label={copied ? t("message.copied") : t("message.copy")}
        className="size-6 text-muted-foreground hover:text-foreground"
      >
        {copied ? <Check className="size-3.5" /> : <Copy className="size-3.5" />}
      </MessageAction>
      {showFeedback && feedbackTargetId ? (
        <>
          <MessageAction
            onClick={() => chooseRating("up")}
            tooltip={t("message.helpful")}
            label={t("message.markHelpful")}
            className={[
              "size-6 hover:text-foreground",
              feedback?.rating === "up" ? "text-foreground" : "text-muted-foreground",
            ].join(" ")}
            aria-pressed={feedback?.rating === "up"}
          >
            <ThumbsUp className="size-3.5" />
          </MessageAction>
          <MessageAction
            onClick={() => chooseRating("down")}
            tooltip={t("message.notHelpful")}
            label={t("message.markNotHelpful")}
            className={[
              "size-6 hover:text-foreground",
              feedback?.rating === "down" ? "text-foreground" : "text-muted-foreground",
            ].join(" ")}
            aria-pressed={feedback?.rating === "down"}
          >
            <ThumbsDown className="size-3.5" />
          </MessageAction>
        </>
      ) : null}
      {threadFork.enabled && threadFork.onFork && feedbackTargetId ? (
        <MessageAction
          onClick={() =>
            threadFork.onFork?.({
              targetMessageId: resolveSessionMessageFeedbackTargetId(feedbackTargetId, timestamp),
              assistantText: content,
            })
          }
          tooltip={t("message.newThread")}
          label={t("message.newThread")}
          className="size-6 text-muted-foreground hover:text-foreground"
        >
          <GitFork className="size-3.5" />
        </MessageAction>
      ) : null}
      <span className="ml-1 text-[11px] tabular-nums text-muted-foreground/70">
        {formatSessionMessageTimestamp(timestamp)}
      </span>
      {showFeedback && feedbackTargetId ? (
        <SessionMessageFeedbackDialog
          open={dialogOpen}
          rating={dialogRating}
          reasons={reasons}
          detail={detail}
          saving={saving}
          onOpenChange={setDialogOpen}
          onReasonsChange={setReasons}
          onDetailChange={setDetail}
          onSubmit={() => {
            void saveFeedback(dialogRating, reasons, detail).then((saved) => {
              if (saved) setDialogOpen(false);
            });
          }}
        />
      ) : null}
    </MessageActions>
  );
}

