"use client";

import { AUTOMATION_SETUP_CONNECTED_INTEGRATIONS_QUESTION_ID } from "@lib/automation-setup-connected-integrations";
import { formatPiiTypeLabel, maskPiiForClientPreview } from "@lib/pii/client";
import { TOKEN_PATTERN } from "@lib/pii/token";
import {
  type AskUserRequest,
  type AskUserResult,
  formatAskUserResultSummary,
  type NormalizedAskUserQuestion,
  resolveAskUserSubmitLabel,
} from "@lib/session-ask-user";
import { isAskUserQuestionVisible } from "@lib/session-ask-user-conditional";
import { partitionAskUserQuestions } from "@lib/session-ask-user-single-choice";
import { Link } from "@tanstack/react-router";
import { SessionAskUserReceipt } from "@web/components/session-ask-user-receipt";
import { TurnChromeCard } from "@web/components/session-chat/turn-chrome-card";
import {
  findOtherLikeAskUserOption,
  isOtherLikeAskUserOption,
} from "@web/lib/ask-user-other-option";
import {
  type AskUserDraftAnswers,
  draftToAskUserAnswers,
  validateAskUserDraft,
} from "@web/lib/session-ask-user-draft";
import {
  awaitSessionCommandDispatch,
  type SessionCommandDispatchHandlerResult,
} from "@web/lib/session-command-dispatch";
import { workBlockIconClass } from "@web/lib/session-work-block-chrome";
import { useSessionAskUserDraft } from "@web/lib/use-session-ask-user-draft";
import { cn } from "@web/lib/utils";
import { MessageCircleQuestion } from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import { Button } from "@/components/ui/button";
import {
  Questionnaire,
  QuestionnaireActions,
  QuestionnaireChoice,
  QuestionnaireChoiceDescription,
  QuestionnaireChoices,
  QuestionnaireDescription,
  QuestionnaireError,
  QuestionnaireInput,
  QuestionnaireItem,
  QuestionnaireNext,
  QuestionnairePrevious,
  QuestionnaireSubmit,
  QuestionnaireTitle,
} from "@/components/ui/questionnaire";

/** Announce draft answers without reading raw PII into screen readers (TAC-546). */
function announceAskUserDraftSummary(summary: string): string {
  const preview = maskPiiForClientPreview(summary);
  if (preview.piiSpans.length === 0) return summary;
  return preview.content.replace(TOKEN_PATTERN, (_token, type: string) => {
    return `protected ${formatPiiTypeLabel(type)}`;
  });
}

type DraftAnswers = AskUserDraftAnswers;

function askUserFixedChoices(question: NormalizedAskUserQuestion) {
  return question.options.filter((option) => !isOtherLikeAskUserOption(option));
}

function askUserFreeform(question: NormalizedAskUserQuestion): {
  show: boolean;
  label: string;
  placeholder: string;
} | null {
  if (question.type === "text") {
    return {
      show: true,
      label: question.label,
      placeholder: question.placeholder?.trim() || "Type your answer",
    };
  }
  const otherLike = findOtherLikeAskUserOption(question.options);
  if (!question.allowOther && !otherLike) return null;
  return {
    show: true,
    label: otherLike?.label ?? `${question.label} other answer`,
    placeholder: otherLike?.label ?? question.placeholder?.trim() ?? "Type your answer",
  };
}

function AskUserStepProgress({ current, total }: { current: number; total: number }) {
  return (
    <span
      className="pt-0.5 pr-1 text-xs tabular-nums text-sidebar-foreground/65"
      aria-live="polite"
    >
      Question {current} of {total}
    </span>
  );
}

const autoSubmittedAskUserRequestIds = new Set<string>();

export function SessionAskUserForm({
  request,
  resolution,
  onSubmit,
  onCancel,
  className,
  sessionId,
  defaultExpanded = false,
  hideHeader = false,
}: {
  request: AskUserRequest;
  resolution?: AskUserResult;
  onSubmit?: (result: AskUserResult) => SessionCommandDispatchHandlerResult;
  onCancel?: () => SessionCommandDispatchHandlerResult;
  className?: string;
  sessionId?: string;
  /** When rendering a resolved receipt, start expanded (dev gallery / tests). */
  defaultExpanded?: boolean;
  /**
   * Hide header chrome when an outer card already shows it
   * (e.g. Teams Needs You rail).
   */
  hideHeader?: boolean;
}) {
  const { t } = useTranslation("common");
  const sendAnswersError = t("askUser.errors.send");
  const cancelQuestionsError = t("askUser.errors.cancel");
  const { visibleQuestions: baseVisibleQuestions, implicitAnswers } = useMemo(
    () => partitionAskUserQuestions(request.questions),
    [request.questions],
  );
  const {
    draft,
    setDraft,
    activeQuestionId,
    setActiveQuestionId,
    submitting,
    setSubmitting,
    draftResetKey,
  } = useSessionAskUserDraft({
    sessionId,
    requestId: request.requestId,
    questions: request.questions,
    resolution,
  });
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [dispatchError, setDispatchError] = useState<string | null>(null);
  const autoSubmittedRef = useRef(false);
  const { visibleQuestions, questionnaireItems } = useMemo(() => {
    const answerSnapshot = Object.fromEntries(
      Object.entries(draft).map(([id, entry]) => [
        id,
        { value: entry.value, useOther: entry.useOther },
      ]),
    );
    const nextVisible = baseVisibleQuestions.filter((question) =>
      isAskUserQuestionVisible(question, answerSnapshot, baseVisibleQuestions),
    );
    return {
      visibleQuestions: nextVisible,
      questionnaireItems: nextVisible.map((question) => ({
        name: question.id,
        required:
          question.required &&
          !(
            question.id === AUTOMATION_SETUP_CONNECTED_INTEGRATIONS_QUESTION_ID &&
            question.options.length === 0
          ),
        choices: askUserFixedChoices(question).map((option) => ({ value: option.value })),
      })),
    };
  }, [baseVisibleQuestions, draft]);
  const matchedActiveQuestionIndex = visibleQuestions.findIndex(
    (question) => question.id === activeQuestionId,
  );
  const activeQuestionIndex = matchedActiveQuestionIndex >= 0 ? matchedActiveQuestionIndex : 0;
  const activeQuestion = visibleQuestions[activeQuestionIndex];
  const requestSubtitle = request.description?.trim() || undefined;

  // biome-ignore lint/correctness/useExhaustiveDependencies: reset form chrome when draft identity changes
  useEffect(() => {
    autoSubmittedRef.current = false;
    setErrors({});
    setDispatchError(null);
  }, [draftResetKey]);

  useEffect(() => {
    if (visibleQuestions.length === 0) {
      if (activeQuestionId !== null) setActiveQuestionId(null);
      return;
    }
    // Keep the in-progress step. Do not snap back to question 1 when the
    // visible list briefly churns (Needs You attention refresh / remount).
    if (activeQuestionId) return;
    setActiveQuestionId(visibleQuestions[0]?.id ?? null);
  }, [activeQuestionId, setActiveQuestionId, visibleQuestions]);

  const submitImplicitAnswers = useCallback(async () => {
    if (!onSubmit) return;
    autoSubmittedRef.current = true;
    autoSubmittedAskUserRequestIds.add(request.requestId);
    setSubmitting(true);
    try {
      const result = await awaitSessionCommandDispatch(
        onSubmit({
          requestId: request.requestId,
          cancelled: false,
          answers: implicitAnswers,
        }),
      );
      if (!result.ok) {
        throw new Error(result.message?.trim() || sendAnswersError);
      }
    } catch (error) {
      autoSubmittedRef.current = false;
      autoSubmittedAskUserRequestIds.delete(request.requestId);
      setDispatchError(error instanceof Error ? error.message : sendAnswersError);
    } finally {
      setSubmitting(false);
    }
  }, [implicitAnswers, onSubmit, request.requestId, sendAnswersError, setSubmitting]);

  useEffect(() => {
    if (resolution || !onSubmit || autoSubmittedRef.current) return;
    if (visibleQuestions.length > 0) return;
    if (implicitAnswers.length === 0) return;
    if (autoSubmittedAskUserRequestIds.has(request.requestId)) return;
    void submitImplicitAnswers();
  }, [
    implicitAnswers.length,
    onSubmit,
    request.requestId,
    resolution,
    submitImplicitAnswers,
    visibleQuestions.length,
  ]);

  useEffect(() => {
    if (resolution || !activeQuestion?.id) return;
    const requestId = request.requestId;
    const questionId = activeQuestion.id;
    const timer = window.setTimeout(() => {
      const item = document.querySelector(
        `[data-ask-user-request="${requestId}"] [data-ask-user-question="${questionId}"]`,
      );
      if (!(item instanceof Element) || item.hasAttribute("hidden")) return;
      const textInput = item.querySelector(
        'input[data-slot="questionnaire-input"]:not([disabled])',
      );
      const choiceInput = item.querySelector(
        'input[data-slot="questionnaire-choice-input"]:not([disabled])',
      );
      const target = textInput && !choiceInput ? textInput : (choiceInput ?? textInput ?? item);
      if (target instanceof HTMLElement) {
        target.focus();
      }
    }, 0);
    return () => window.clearTimeout(timer);
  }, [activeQuestion?.id, request.requestId, resolution]);

  const previewSummary = useMemo(() => {
    const questionsForPreview =
      visibleQuestions.length > 1
        ? visibleQuestions.slice(activeQuestionIndex, activeQuestionIndex + 1)
        : visibleQuestions;
    const answers = [
      ...(visibleQuestions.length > 1 ? [] : implicitAnswers),
      ...draftToAskUserAnswers(questionsForPreview, draft),
    ];
    const summary = formatAskUserResultSummary(request, {
      requestId: request.requestId,
      cancelled: false,
      answers,
    });
    return announceAskUserDraftSummary(summary);
  }, [activeQuestionIndex, draft, implicitAnswers, request, visibleQuestions]);

  const activeStepErrors = useMemo(
    () => (activeQuestion ? validateAskUserDraft([activeQuestion], draft) : {}),
    [activeQuestion, draft],
  );
  const allStepErrors = useMemo(
    () => validateAskUserDraft(visibleQuestions, draft),
    [draft, visibleQuestions],
  );

  if (resolution) {
    return (
      <SessionAskUserReceipt
        request={request}
        result={resolution}
        className={className}
        sessionId={sessionId}
        defaultExpanded={defaultExpanded}
      />
    );
  }

  if (visibleQuestions.length === 0) {
    return dispatchError ? (
      <TurnChromeCard
        state="default"
        className={className}
        icon={<MessageCircleQuestion className="size-4 shrink-0" aria-hidden="true" />}
        title={request.title?.trim() || "A few questions"}
        description={
          requestSubtitle ? <span data-ask-user-subtitle="">{requestSubtitle}</span> : undefined
        }
      >
        <div className="flex items-center justify-between gap-3 px-3 py-2">
          <p className="text-sm text-destructive">{dispatchError}</p>
          <Button
            type="button"
            size="sm"
            variant="outline"
            onClick={() => {
              setDispatchError(null);
              void submitImplicitAnswers();
            }}
          >
            {t("actions.retry")}
          </Button>
        </div>
      </TurnChromeCard>
    ) : null;
  }

  const updateQuestion = (questionId: string, next: DraftAnswers[string]) => {
    setDraft((previous) => ({ ...previous, [questionId]: next }));
    setErrors((previous) => {
      if (!previous[questionId]) return previous;
      const copy = { ...previous };
      delete copy[questionId];
      return copy;
    });
  };

  const handleSubmit = () => {
    if (submitting) return;
    const nextErrors = validateAskUserDraft(visibleQuestions, draft);
    setErrors(nextErrors);
    const firstInvalid = visibleQuestions.find((question) => nextErrors[question.id]);
    if (firstInvalid) {
      setActiveQuestionId(firstInvalid.id);
      return;
    }
    if (!onSubmit) return;
    setSubmitting(true);
    setDispatchError(null);
    void (async () => {
      try {
        const result = await awaitSessionCommandDispatch(
          onSubmit({
            requestId: request.requestId,
            cancelled: false,
            answers: [...implicitAnswers, ...draftToAskUserAnswers(visibleQuestions, draft)],
          }),
        );
        if (!result.ok) {
          setDispatchError(result.message?.trim() || sendAnswersError);
        }
      } catch (error) {
        setDispatchError(error instanceof Error ? error.message : sendAnswersError);
      } finally {
        setSubmitting(false);
      }
    })();
  };

  const handleCancel = () => {
    if (submitting) return;
    if (!onCancel) return;
    setSubmitting(true);
    setDispatchError(null);
    void (async () => {
      try {
        const result = await awaitSessionCommandDispatch(onCancel());
        if (!result.ok) {
          setDispatchError(result.message?.trim() || cancelQuestionsError);
        }
      } catch (error) {
        setDispatchError(error instanceof Error ? error.message : cancelQuestionsError);
      } finally {
        setSubmitting(false);
      }
    })();
  };

  const isMultiStep = visibleQuestions.length > 1;
  const isLastQuestion = activeQuestionIndex === visibleQuestions.length - 1;
  const primaryActionBlocked =
    isMultiStep && !isLastQuestion
      ? Object.keys(activeStepErrors).length > 0
      : Object.keys(allStepErrors).length > 0;

  const handleItemChange = (nextId: string) => {
    const nextIndex = visibleQuestions.findIndex((question) => question.id === nextId);
    if (nextIndex > activeQuestionIndex && activeQuestion) {
      const nextErrors = validateAskUserDraft([activeQuestion], draft);
      setErrors((previous) => ({ ...previous, ...nextErrors }));
      if (Object.keys(nextErrors).length > 0) return;
    }
    setActiveQuestionId(nextId);
  };

  return (
    <Questionnaire
      className="min-w-0"
      data-ask-user-form=""
      data-ask-user-request={request.requestId}
      item={activeQuestion?.id}
      items={questionnaireItems}
      shortcuts="letters"
      noValidate
      onItemChange={handleItemChange}
      onSubmit={(event) => {
        event.preventDefault();
        handleSubmit();
      }}
    >
      <TurnChromeCard
        as="div"
        state="default"
        presentation={hideHeader ? "receipt" : "dialog"}
        className={className}
        hideHeader={hideHeader}
        icon={
          <MessageCircleQuestion
            className={cn("size-4 shrink-0", workBlockIconClass("default"))}
            aria-hidden="true"
          />
        }
        title={activeQuestion?.prompt.trim() || request.title?.trim() || "A few questions"}
        titleWrap
        description={
          !hideHeader && requestSubtitle ? (
            <span data-ask-user-subtitle="">{requestSubtitle}</span>
          ) : undefined
        }
        headerActions={
          isMultiStep ? (
            <AskUserStepProgress
              current={activeQuestionIndex + 1}
              total={visibleQuestions.length}
            />
          ) : undefined
        }
        footer={
          <div className="flex w-full flex-col gap-1.5">
            <QuestionnaireActions>
              {isLastQuestion ? (
                <QuestionnaireSubmit
                  disabled={submitting || primaryActionBlocked}
                  data-ask-user-submit=""
                  data-ask-user-primary-blocked={primaryActionBlocked ? "true" : "false"}
                >
                  {submitting
                    ? t("askUser.sending")
                    : resolveAskUserSubmitLabel(request.submitLabel)}
                </QuestionnaireSubmit>
              ) : (
                <QuestionnaireNext
                  disabled={submitting || primaryActionBlocked}
                  data-ask-user-submit=""
                  data-ask-user-primary-blocked={primaryActionBlocked ? "true" : "false"}
                >
                  Continue
                </QuestionnaireNext>
              )}
              {isMultiStep && activeQuestionIndex > 0 ? (
                <QuestionnairePrevious disabled={submitting} data-ask-user-back="">
                  Back
                </QuestionnairePrevious>
              ) : null}
              {!hideHeader ? (
                <Button
                  type="button"
                  size="sm"
                  variant="ghost"
                  className={cn(isMultiStep && "ml-auto")}
                  disabled={submitting}
                  data-ask-user-cancel=""
                  onClick={handleCancel}
                >
                  Cancel
                </Button>
              ) : null}
            </QuestionnaireActions>
            {dispatchError ? <p className="text-xs text-destructive">{dispatchError}</p> : null}
          </div>
        }
        footerClassName="pt-0"
      >
        <div className="px-3 pt-1 pb-2">
          {visibleQuestions.map((question, questionIndex) => {
            const entry = draft[question.id];
            if (!entry) return null;
            const error = errors[question.id];
            const freeform = askUserFreeform(question);
            const choices = askUserFixedChoices(question);
            const isConnectedIntegrations =
              question.id === AUTOMATION_SETUP_CONNECTED_INTEGRATIONS_QUESTION_ID;
            const emptyConnectedIntegrations =
              isConnectedIntegrations && question.options.length === 0;

            return (
              <QuestionnaireItem
                key={question.id}
                name={question.id}
                required={question.required && !emptyConnectedIntegrations}
                multiple={question.type === "checkbox"}
                invalid={Boolean(error)}
                data-ask-user-question={question.id}
                aria-label={
                  isMultiStep
                    ? `Question ${questionIndex + 1} of ${visibleQuestions.length}`
                    : undefined
                }
              >
                <QuestionnaireTitle className={hideHeader ? undefined : "sr-only"}>
                  {question.prompt}
                </QuestionnaireTitle>
                {hideHeader && requestSubtitle ? (
                  <QuestionnaireDescription data-ask-user-subtitle="">
                    {requestSubtitle}
                  </QuestionnaireDescription>
                ) : null}
                {emptyConnectedIntegrations ? (
                  <QuestionnaireDescription>
                    You have not connected any apps yet.{" "}
                    <Link
                      to="/settings/$section"
                      params={{ section: "integrations" }}
                      className="text-blue-600 underline-offset-4 hover:underline"
                    >
                      Connect apps in Settings
                    </Link>{" "}
                    to include them here, or leave this blank and continue.
                  </QuestionnaireDescription>
                ) : null}
                {question.type === "text" && freeform ? (
                  <QuestionnaireInput
                    aria-label={freeform.label}
                    placeholder={freeform.placeholder}
                    value={String(entry.value ?? "")}
                    onChange={(event) =>
                      updateQuestion(question.id, {
                        ...entry,
                        value: event.target.value,
                      })
                    }
                  />
                ) : null}
                {question.type !== "text" && !emptyConnectedIntegrations ? (
                  <QuestionnaireChoices>
                    {choices.map((option) => {
                      const checked =
                        question.type === "checkbox"
                          ? Array.isArray(entry.value) && entry.value.includes(option.value)
                          : !entry.useOther && String(entry.value || "") === option.value;
                      return (
                        <QuestionnaireChoice
                          key={option.value}
                          value={option.value}
                          checked={checked}
                          data-state={checked ? "checked" : "unchecked"}
                          data-ask-user-option={option.value}
                          onClick={() => {
                            if (question.type === "checkbox") {
                              const selected = Array.isArray(entry.value) ? [...entry.value] : [];
                              const next = selected.includes(option.value)
                                ? selected.filter((value) => value !== option.value)
                                : [...selected, option.value];
                              updateQuestion(question.id, { ...entry, value: next });
                              return;
                            }
                            updateQuestion(question.id, {
                              ...entry,
                              useOther: false,
                              value: option.value,
                              otherText: "",
                            });
                          }}
                          onChange={(event) => {
                            if (question.type === "checkbox") {
                              const selected = Array.isArray(entry.value) ? [...entry.value] : [];
                              const next = event.target.checked
                                ? [...new Set([...selected, option.value])]
                                : selected.filter((value) => value !== option.value);
                              updateQuestion(question.id, { ...entry, value: next });
                              return;
                            }
                            updateQuestion(question.id, {
                              ...entry,
                              useOther: false,
                              value: option.value,
                              otherText: "",
                            });
                          }}
                        >
                          <span className="text-sm font-normal">{option.label}</span>
                          {option.description ? (
                            <QuestionnaireChoiceDescription>
                              {option.description}
                            </QuestionnaireChoiceDescription>
                          ) : null}
                        </QuestionnaireChoice>
                      );
                    })}
                    {freeform ? (
                      <QuestionnaireInput
                        aria-label={freeform.label}
                        placeholder={freeform.placeholder}
                        value={entry.otherText}
                        onChange={(event) => {
                          const nextText = event.target.value;
                          if (question.type === "checkbox") {
                            updateQuestion(question.id, {
                              ...entry,
                              useOther: nextText.trim().length > 0,
                              otherText: nextText,
                            });
                            return;
                          }
                          updateQuestion(question.id, {
                            ...entry,
                            useOther: true,
                            value: "",
                            otherText: nextText,
                          });
                        }}
                      />
                    ) : null}
                  </QuestionnaireChoices>
                ) : null}
                <QuestionnaireError>{error}</QuestionnaireError>
              </QuestionnaireItem>
            );
          })}
        </div>

        <p className="sr-only" aria-live="polite">
          {previewSummary}
        </p>
      </TurnChromeCard>
    </Questionnaire>
  );
}

import "@web/i18n";
import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, test } from "vitest";
import { SessionAskUserForm } from "./session-ask-user-form";

const request = {
  requestId: "req_app_builder_clarify",
  title: "Clarify your app requirements",
  questions: [
    {
      id: "audience",
      type: "radio" as const,
      prompt: "Who is this app for?",
      label: "Audience",
      options: [
        { value: "customers", label: "Customers" },
        { value: "staff", label: "Staff" },
      ],
      allowOther: false,
      required: true,
    },
  ],
};

describe("SessionAskUserForm radio questions", () => {
  test("starts choice inputs controlled so the first selection cannot change mode", () => {
    const html = renderToStaticMarkup(<SessionAskUserForm request={request} />);
    const inputs = html.match(/<input[^>]*type="radio"[^>]*>/g) ?? [];
    expect(inputs.length).toBe(2);
    expect(html).toContain('data-unchecked=""');
  });

  test("associates each option row with its radio control for one-click selection", () => {
    const html = renderToStaticMarkup(<SessionAskUserForm request={request} />);
    expect(html).toContain('data-ask-user-option="customers"');
    expect(html).toContain('value="customers"');
    expect(html).toMatch(/<label[^>]*data-ask-user-option="customers"/);
    expect(html).toMatch(/<input[^>]*type="radio"[^>]*value="customers"/);
  });

  test("exposes stable automation hooks for form, options, and submit", () => {
    const html = renderToStaticMarkup(<SessionAskUserForm request={request} />);
    expect(html).toContain('data-ask-user-form=""');
    expect(html).toContain('data-ask-user-request="req_app_builder_clarify"');
    expect(html).toContain('data-ask-user-question="audience"');
    expect(html).toContain('data-ask-user-option="customers"');
    expect(html).toContain('data-ask-user-option="staff"');
    expect(html).toContain('data-ask-user-submit=""');
    expect(html).toContain('data-ask-user-cancel=""');
  });

  test("routes labeled different/custom options into the freeform answer", () => {
    const html = renderToStaticMarkup(
      <SessionAskUserForm
        request={{
          requestId: "req_schedule",
          title: "When should it run?",
          questions: [
            {
              id: "schedule",
              type: "radio",
              prompt: "When should it run?",
              label: "Schedule",
              options: [
                { value: "friday", label: "Friday at 2:00 PM" },
                { value: "diff", label: "A different weekly time" },
              ],
              allowOther: false,
              required: true,
            },
          ],
        }}
      />,
    );
    expect(html).toContain('value="friday"');
    expect(html).toContain("A different weekly time");
    expect(html).not.toContain('value="diff"');
    expect(html).not.toContain('value="__other__"');
    expect(html).toContain('data-slot="questionnaire-input"');
  });

  test("renders request description as a subtitle under the question title", () => {
    const html = renderToStaticMarkup(
      <SessionAskUserForm
        request={{
          ...request,
          description: "Choose the audience that will use this first.",
        }}
      />,
    );
    expect(html).toContain('data-ask-user-subtitle=""');
    expect(html).toContain("Choose the audience that will use this first.");
  });

  test("omits the subtitle when description is empty", () => {
    const html = renderToStaticMarkup(<SessionAskUserForm request={request} />);
    expect(html).not.toContain("data-ask-user-subtitle");
  });

  test("defaults the submit button to Send", () => {
    const html = renderToStaticMarkup(<SessionAskUserForm request={request} />);
    expect(html).toContain(">Send<");
    expect(html).not.toContain("Save answers");
  });

  test("uses a custom two-word submit label", () => {
    const html = renderToStaticMarkup(
      <SessionAskUserForm request={{ ...request, submitLabel: "Use format" }} />,
    );
    expect(html).toContain(">Use format<");
    expect(html).not.toContain(">Send<");
  });
});

