import {
  genesisLocalStorageKey,
  readGenesisLocalStorageItem,
  writeGenesisLocalStorageItem,
} from "@web/lib/genesis-local-storage";
import i18n from "i18next";
import LanguageDetector from "i18next-browser-languagedetector";
import { initReactI18next } from "react-i18next";
import {
  DEFAULT_LOCALE,
  LOCALE_STORAGE_SUFFIX,
  normalizeLocale,
  SUPPORTED_LOCALES,
  type SupportedLocale,
} from "./locales";
import enCommon from "./locales/en/common.json";
import enSessions from "./locales/en/sessions.json";
import enSettings from "./locales/en/settings.json";
import enShell from "./locales/en/shell.json";
import ptBRCommon from "./locales/pt-BR/common.json";
import ptBRSessions from "./locales/pt-BR/sessions.json";
import ptBRSettings from "./locales/pt-BR/settings.json";
import ptBRShell from "./locales/pt-BR/shell.json";
import "./types";

export {
  DEFAULT_LOCALE,
  isSupportedLocale,
  LOCALE_STORAGE_SUFFIX,
  normalizeLocale,
  SUPPORTED_LOCALES,
  type SupportedLocale,
} from "./locales";

const resources = {
  en: {
    common: enCommon,
    sessions: enSessions,
    settings: enSettings,
    shell: enShell,
  },
  "pt-BR": {
    common: ptBRCommon,
    sessions: ptBRSessions,
    settings: ptBRSettings,
    shell: ptBRShell,
  },
} as const;

function applyDocumentLang(locale: string): void {
  if (typeof document === "undefined") return;
  document.documentElement.lang = normalizeLocale(locale);
}

const genesisLocaleDetector = {
  name: "genesisLocalStorage",
  lookup(): string | undefined {
    const stored = readGenesisLocalStorageItem(LOCALE_STORAGE_SUFFIX);
    return stored ?? undefined;
  },
  cacheUserLanguage(lng: string): void {
    writeGenesisLocalStorageItem(LOCALE_STORAGE_SUFFIX, normalizeLocale(lng));
  },
};

const languageDetector = new LanguageDetector();
languageDetector.addDetector(genesisLocaleDetector);

void i18n
  .use(languageDetector)
  .use(initReactI18next)
  .init({
    resources,
    supportedLngs: [...SUPPORTED_LOCALES],
    fallbackLng: DEFAULT_LOCALE,
    defaultNS: "common",
    ns: ["common", "sessions", "settings", "shell"],
    interpolation: {
      escapeValue: false,
    },
    detection: {
      order: ["genesisLocalStorage", "navigator"],
      caches: ["genesisLocalStorage"],
      lookupLocalStorage: genesisLocalStorageKey(LOCALE_STORAGE_SUFFIX),
      convertDetectedLanguage: (lng) => normalizeLocale(lng),
    },
  });

applyDocumentLang(i18n.resolvedLanguage ?? i18n.language ?? DEFAULT_LOCALE);

i18n.on("languageChanged", (lng) => {
  applyDocumentLang(lng);
});

export function getCurrentLocale(): SupportedLocale {
  return normalizeLocale(i18n.resolvedLanguage ?? i18n.language);
}

export async function setAppLocale(locale: SupportedLocale): Promise<void> {
  const next = normalizeLocale(locale);
  writeGenesisLocalStorageItem(LOCALE_STORAGE_SUFFIX, next);
  await i18n.changeLanguage(next);
}

export default i18n;

