import { readFileSync } from "node:fs";
import path from "node:path";
import { defineConfig } from "vitest/config";

/** Load `with { type: "text" }` markdown imports as raw strings. */
function textImportPlugin() {
  return {
    name: "genesis-text-import",
    enforce: "pre" as const,
    load(id: string) {
      const clean = id.split("?")[0] ?? id;
      if (clean.endsWith(".md") || clean.endsWith(".html") || clean.endsWith(".css")) {
        return `export default ${JSON.stringify(readFileSync(clean, "utf8"))};`;
      }
      return null;
    },
  };
}

export default defineConfig({
  plugins: [textImportPlugin()],
  test: {
    globals: false,
    environment: "node",
    include: [
      "src/**/*.{test,spec}.{ts,tsx}",
      "scripts/**/*.{test,spec}.{ts,tsx}",
      // Vite plugins live next to vite.config.ts (not under src/).
      "vite-plugin*.test.ts",
    ],
    exclude: ["**/node_modules/**", "**/dist/**"],
    testTimeout: 30_000,
    hookTimeout: 30_000,
    pool: "forks",
  },
  resolve: {
    alias: [
      { find: "@web/types", replacement: path.resolve(__dirname, "src/web/types") },
      { find: "@/components", replacement: path.resolve(__dirname, "src/web/components") },
      { find: "@agent", replacement: path.resolve(__dirname, "src/agent") },
      { find: "@api", replacement: path.resolve(__dirname, "src/api") },
      { find: "@web", replacement: path.resolve(__dirname, "src/web") },
      { find: "@lib", replacement: path.resolve(__dirname, "src/lib") },
      { find: "@", replacement: path.resolve(__dirname, "src") },
    ],
  },
});

