export const SESSION_BOOTSTRAP_WAIT_MS = 10_000;

function clearAuthCallbackErrorFromUrl() {
  const url = new URL(window.location.href);
  if (!url.searchParams.has("error")) return;
  url.searchParams.delete("error");
  url.searchParams.delete("error_description");
  window.history.replaceState({}, "", `${url.pathname}${url.search}${url.hash}`);
}

function isDevUiRoute(): boolean {
  return import.meta.env.DEV && isDevUiGalleryRoute();
}

function DevUiAppShell({ children }: { children: ReactElement }): ReactElement {
  return (
    <SessionLogShell>
      <ConnectivityProvider>{children}</ConnectivityProvider>
    </SessionLogShell>
  );
}

export function App(): ReactElement | null {
  return (
    <ThemeProvider defaultTheme="system">
      {isDevUiRoute() ? (
        <DevUiAppShell>
          <RouterProvider
            router={router}
            context={{
              user: undefined!,
              logout: () => Promise.resolve(),
            }}
          />
        </DevUiAppShell>
      ) : (
        <AuthenticatedApp />
      )}
    </ThemeProvider>
  );
}

function AppBootstrapLoadingState(): ReactElement {
  return <GenesisLoadingState className="min-h-screen" />;
}

export function resolveSessionBootstrapGate(input: {
  waiting: boolean;
  waitExpired: boolean;
}): "loading" | "unavailable" | null {
  if (!input.waiting) return null;
  return input.waitExpired ? "unavailable" : "loading";
}

export function scheduleSessionBootstrapWait(onElapsed: () => void): () => void {
  const timer = window.setTimeout(onElapsed, SESSION_BOOTSTRAP_WAIT_MS);
  return () => window.clearTimeout(timer);
}

function AuthFailureState({ description }: { description: string }): ReactElement {
  const { t } = useTranslation("onboarding");
  return (
    <PublicFocusPage>
      <PublicFocusCard title={t("auth.errors.signInFailedTitle")} description={description}>
        <div className="mt-8 flex flex-col items-center gap-8">
          <PublicFocusCta
            type="button"
            onClick={() => {
              clearAuthCallbackErrorFromUrl();
              login(window.location.pathname + window.location.search);
            }}
          >
            {t("auth.actions.tryAgain")}
          </PublicFocusCta>
        </div>
      </PublicFocusCard>
    </PublicFocusPage>
  );
}

export function SessionBootstrapUnavailableState(): ReactElement {
  const { t } = useTranslation("onboarding");
  return <AuthFailureState description={t("auth.errors.unavailable")} />;
