      return;
    }
    return scheduleSessionBootstrapWait(() => setWaitExpired(true));
  }, [waiting]);

  return waitExpired;
}

function useBriefingOnboardBootstrap(user: { id: string } | null, isPending: boolean): boolean {
  const needsOnboardCheck =
    !isPending && Boolean(user) && shouldResolveOnboardBeforeAppShell(window.location.pathname);
  const onboardQuery = useOnboardStatus({
    enabled: needsOnboardCheck,
    userId: user?.id,
  });

  useEffect(() => {
    if (!user || !onboardQuery.isSuccess) return;
    syncCachedOnboarded(user.id, onboardQuery.data);
  }, [onboardQuery.data, onboardQuery.isSuccess, user]);

  if (isPending || !user) return false;
  return resolveBriefingOnboardBootstrap({
    pathname: window.location.pathname,
    onboarded: onboardQuery.data,
    isSuccess: onboardQuery.isSuccess,
    cachedOnboarded: hasCachedOnboarded(user.id),
  });
}

function PublicShellRouter({
  user,
  logout,
}: {
  user: {
    id: string;
    email: string;
    name?: string | null;
    image?: string | null;
  } | null;
  logout: () => Promise<void>;
}): ReactElement {
  // Share (and other public shells) render session message chrome that reads
  // appearance prefs. The authenticated app already wraps this provider.
  return (
    <AppearancePreferencesProvider>
      <RouterProvider
        router={router}
        context={{
          user: user ?? undefined!,
          logout,
        }}
      />
    </AppearancePreferencesProvider>
  );
}

function AuthenticatedApp(): ReactElement | null {
  const { t } = useTranslation("onboarding");
  const { user, isPending, bootstrapBlocked, logout, localOpsBootstrap } = useSession();
  const [needsGoogleReauth, setNeedsGoogleReauth] = useState(false);
  const [accessRevokedMessage, setAccessRevokedMessage] = useState<string | null>(null);
  const appShellReady = useBriefingOnboardBootstrap(user, isPending);
  const sessionBootstrapWaiting = isPending || bootstrapBlocked;
  const sessionBootstrapWaitExpired = useSessionBootstrapWaitExpired(sessionBootstrapWaiting);
  const sessionBootstrapGate = resolveSessionBootstrapGate({
    waiting: sessionBootstrapWaiting,
    waitExpired: sessionBootstrapWaitExpired,
  });
  const unauthenticatedShell = canRenderUnauthenticatedShell(localOpsBootstrap);

  useEffect(() => {
    const handler = () => setNeedsGoogleReauth(true);
    window.addEventListener(GOOGLE_REAUTH_EVENT, handler);
    return () => window.removeEventListener(GOOGLE_REAUTH_EVENT, handler);
  }, []);

  // Safety net: auth callback failures used to land on `/?error=…` while the
  // session cookie still worked, so the unauthenticated AuthFailureState never
  // rendered and the user saw only Briefing. Surface the message when signed in.
  useEffect(() => {
    if (!user) return;
    const notice = readAuthCallbackNotice(window.location.search, true, t);
    if (!notice) return;
    showAppNotice({
      id: "auth-callback-error",
      title: notice.title,
      description: notice.description,
      durationMs: 12_000,
      actions: isRetryableAuthCallbackError(notice.code)
        ? [
            {
              label: t("auth.actions.tryAgain"),
              onClick: () => {
                window.location.assign(
                  googleIdentityConnectUrl(window.location.pathname + window.location.search, {
                    promptConsent: true,
                  }),
                );
              },
            },
          ]
        : undefined,
    });
    clearAuthCallbackErrorFromUrl();
  }, [t, user]);

  useEffect(() => {
    return subscribeUserAccessRevoked((detail) => {
      setAccessRevokedMessage(detail.message.trim() || t("auth.accessRevoked.defaultMessage"));
      void logout({ redirect: false });
    });
  }, [logout, t]);

  const handleLogout = useCallback(async () => {
    await logout();
  }, [logout]);
  const handleWebSocketAuthenticationRequired = useCallback(() => {
    login(window.location.pathname + window.location.search);
  }, []);

  if (accessRevokedMessage) {
    return (
      <WorkspaceAccessRevokedScreen
        message={accessRevokedMessage}
        onContinue={() => {
          window.sessionStorage.setItem("genesis_logout_redirecting", "true");
          window.location.replace(LOGGED_OUT_REDIRECT_URL);
        }}
      />
    );
  }

  if (sessionBootstrapGate === "unavailable") {
    return <SessionBootstrapUnavailableState />;
  }

  if (
    sessionBootstrapGate === "loading" ||
    (user && !appShellReady && !isPublicShellRoute() && !unauthenticatedShell)
  ) {
    return <AppBootstrapLoadingState />;
  }

  if (!user) {
    if (isLeavingForLogout()) {
      // Never paint an empty #root while redirecting away.
      return <AppBootstrapLoadingState />;
    }

    const authCallbackNotice = readAuthCallbackNotice(window.location.search, false, t);
    if (authCallbackNotice) {
      return <AuthFailureState description={authCallbackNotice.description} />;
    }

    // Public shells + local ops bootstrap (/ops without a session).
    if (unauthenticatedShell) {
      return <PublicShellRouter user={null} logout={() => Promise.resolve()} />;
    }
    login(window.location.pathname + window.location.search);
    // Keep a loading surface up until the login navigation commits.
    return <AppBootstrapLoadingState />;
  }

  if (isPublicShellRoute()) {
    return <PublicShellRouter user={user} logout={handleLogout} />;
  }

  return (
    <AppearancePreferencesProvider>
      <AppNoticeProvider>
        <Suspense fallback={null}>
          <CollectionExportDownloadToast />
          <CollectionImportToast />
        </Suspense>
        <GoogleReauthBanner open={needsGoogleReauth} />
        <Toaster />
        <DevModeProvider>
          <SessionSurfaceDebugAppProvider>
            <VoiceInputProvider>
              <SessionContextProvider>
                <SessionLogShell onAuthenticationRequired={handleWebSocketAuthenticationRequired}>
                  <ConnectivityProvider>
                    <ReleaseUpdateProvider>
                      <CollectionsProvider>
                        <RouterProvider
                          router={router}
                          context={{
                            user,
                            logout: handleLogout,
                          }}
                        />
                      </CollectionsProvider>
                    </ReleaseUpdateProvider>
                  </ConnectivityProvider>
                </SessionLogShell>
              </SessionContextProvider>
            </VoiceInputProvider>
          </SessionSurfaceDebugAppProvider>
        </DevModeProvider>
      </AppNoticeProvider>
    </AppearancePreferencesProvider>
  );
}

