};

/** Display purpose with a capital first letter. */
export function formatExamplePurpose(purpose: string): string {
  const trimmed = purpose.trim();
  if (!trimmed) return trimmed;
  return trimmed.charAt(0).toUpperCase() + trimmed.slice(1);
}

export function contentPackForExample(example: OnboardingPart2Example): OnboardingPart2ContentPack {
  return resolveOnboardingPart2ContentPack(example.contentPack);
}

function teamLabel(example: OnboardingPart2Example, pack: OnboardingPart2ContentPack): string {
  return example.name.trim() || pack.teamName;
}

function purposeLabel(example: OnboardingPart2Example, pack: OnboardingPart2ContentPack): string {
  return example.purpose?.trim() || pack.teamPurpose;
}

function messageForBeat(
  id: OnboardingPart2BeatMessageId,
  example: OnboardingPart2Example,
  fallback: (pack: OnboardingPart2ContentPack) => string,
): string {
  const pack = contentPackForExample(example);
  const fromPack = pack.messages[id]?.trim();
  // Prefer templates when the pack still carries stock FALLBACK copy so
  // example.name / purpose personalization stays reachable.
  const stock = FALLBACK_ONBOARDING_PART2_CONTENT_PACK.messages[id]?.trim();
  if (fromPack && fromPack !== stock) return fromPack;
  return fallback(pack);
}

