export function beatsForSection(section: OnboardingV2Part2Section): OnboardingPart2Beat[] {
  return ONBOARDING_PART2_BEATS.filter((beat) => beat.section === section);
}

export function firstBeatIndexForSection(section: OnboardingV2Part2Section): number {
  const index = ONBOARDING_PART2_BEATS.findIndex((beat) => beat.section === section);
  return index >= 0 ? index : 0;
}

export function nextSectionAfter(
  section: OnboardingV2Part2Section,
): OnboardingV2Part2Section | null {
  if (section === "operating_model") return "collections";
  if (section === "collections") return "apps";
  return null;
}

import { GenesisIcon } from "@web/components/genesis-icon";
import type { OnboardingV2StateResponse } from "@web/lib/onboarding-v2-client";
import { cn } from "@web/lib/utils";
import { Loader2 } from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import { Button } from "@/components/ui/button";
import type { OnboardingV2Part2Section } from "../../../domain/onboarding-v2";
import { ONBOARDING_V2_PART_2_SECTIONS } from "../../../domain/onboarding-v2";
import { OnboardingPart2Demo } from "./onboarding-part2-demo";
import {
  contentPackForExample,
  firstBeatIndexForSection,
  nextSectionAfter,
  ONBOARDING_PART2_BEATS,
  type OnboardingPart2Beat,
  type OnboardingPart2DemoKind,
  type OnboardingPart2Example,
} from "./onboarding-part2-script";

type ChatLine =
  | { id: string; role: "assistant"; text: string; demo?: OnboardingPart2DemoKind }
  | { id: string; role: "user"; text: string };

export type OnboardingPart2Props = {
  state: OnboardingV2StateResponse;
  onPatchPart2: (section: OnboardingV2Part2Section) => Promise<OnboardingV2StateResponse>;
  onComplete: (outcome: "completed" | "skipped") => Promise<OnboardingV2StateResponse>;
  /** Dev UI / tests: start at a beat without waiting for mount PATCH. */
  initialBeatIndex?: number;
  skipAutoStart?: boolean;
};

function SectionDots({ active }: { active: OnboardingV2Part2Section }) {
  const { t } = useTranslation("onboarding");
  const labels: Record<OnboardingV2Part2Section, string> = {
    operating_model: t("onboarding.part2.sections.operatingModel"),
    collections: t("onboarding.part2.sections.collections"),
    apps: t("onboarding.part2.sections.apps"),
  };
  return (
    <div className="flex items-center gap-2">
      <span className="sr-only">
        {t("onboarding.part2.progressAria", { section: labels[active] })}
      </span>
      {ONBOARDING_V2_PART_2_SECTIONS.map((section) => {
        const isActive = section === active;
        const activeIndex = ONBOARDING_V2_PART_2_SECTIONS.indexOf(active);
        const sectionIndex = ONBOARDING_V2_PART_2_SECTIONS.indexOf(section);
        const isDone = sectionIndex < activeIndex;
        return (
          <span
            key={section}
            title={labels[section]}
            className={cn(
              "size-1.5 rounded-sm transition-colors",
              isActive ? "bg-foreground" : isDone ? "bg-foreground/40" : "bg-foreground/15",
            )}
          />
        );
      })}
    </div>
  );
}

function lineFromBeat(beat: OnboardingPart2Beat, example: OnboardingPart2Example): ChatLine {
  return {
    id: `assistant-${beat.id}`,
    role: "assistant",
    text: beat.message(example),
    demo: beat.demo,
  };
}

export function OnboardingPart2({
  state,
  onPatchPart2,
  onComplete,
  initialBeatIndex,
  skipAutoStart = false,
}: OnboardingPart2Props) {
  const { t } = useTranslation("onboarding");
  const example: OnboardingPart2Example = state.selectedExample;
  const contentPack = useMemo(() => contentPackForExample(example), [example]);
  const startedRef = useRef(false);
  const [starting, setStarting] = useState(!skipAutoStart && state.part2.status === "not_started");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [section, setSection] = useState<OnboardingV2Part2Section>(
    state.part2.section ?? "operating_model",
  );
  const [beatIndex, setBeatIndex] = useState(() => {
    if (typeof initialBeatIndex === "number") return initialBeatIndex;
    return firstBeatIndexForSection(state.part2.section ?? "operating_model");
  });
  const [lines, setLines] = useState<ChatLine[]>(() => {
    const start =
      typeof initialBeatIndex === "number"
        ? initialBeatIndex
        : firstBeatIndexForSection(state.part2.section ?? "operating_model");
    const beat = ONBOARDING_PART2_BEATS[start];
    return beat ? [lineFromBeat(beat, example)] : [];
  });
  const scrollerRef = useRef<HTMLDivElement>(null);

  const currentBeat = ONBOARDING_PART2_BEATS[beatIndex] ?? null;

  // When auto-start PATCH returns a generated pack, refresh the opening line
  // while the transcript is still a single beat (before the user advances).
  useEffect(() => {
    if (lines.length !== 1) return;
    const beat = ONBOARDING_PART2_BEATS[beatIndex];
    if (!beat) return;
    const next = lineFromBeat(beat, example);
    setLines((prev) => (prev[0]?.text === next.text ? prev : [next]));
  }, [beatIndex, example, lines.length]);

  // biome-ignore lint/correctness/useExhaustiveDependencies: scroll when transcript or beat changes
  useEffect(() => {
    scrollerRef.current?.scrollTo({ top: scrollerRef.current.scrollHeight, behavior: "smooth" });
  }, [beatIndex, lines.length]);

  useEffect(() => {
    if (skipAutoStart || startedRef.current) return;
    if (state.part2.status !== "not_started") {
      startedRef.current = true;
      setStarting(false);
      return;
    }
    startedRef.current = true;
    setStarting(true);
    setError(null);
    void onPatchPart2("operating_model")
      .then((next) => {
        setSection(next.part2.section ?? "operating_model");
        setStarting(false);
      })
      .catch(() => {
        startedRef.current = false;
        setStarting(false);
        setError(t("onboarding.part2.startError"));
      });
  }, [onPatchPart2, skipAutoStart, state.part2.status, t]);

  const sectionLabels: Record<OnboardingV2Part2Section, string> = {
    operating_model: t("onboarding.part2.sections.operatingModel"),
    collections: t("onboarding.part2.sections.collections"),
    apps: t("onboarding.part2.sections.apps"),
  };
  const actionLabels = useMemo<Record<OnboardingPart2Beat["id"], string>>(
    () => ({
      "om-intro": t("onboarding.part2.actions.letsGo"),
      "om-team": t("onboarding.part2.actions.showPlaybook"),
      "om-playbook": t("onboarding.part2.actions.showAutomations"),
      "om-automation": t("onboarding.part2.actions.whatNeedsMe"),
      "om-attention": t("onboarding.part2.actions.nextRecords"),
      "col-demo": t("onboarding.part2.actions.nextApps"),
      "apps-demo": t("onboarding.part2.actions.gotIt"),
      "apps-handoff": t("onboarding.part2.actions.goToBriefing"),
    }),
    [t],
  );
  const sectionLabel = sectionLabels[section];

  const handleAction = useCallback(async () => {
    if (!currentBeat || busy || starting) return;
    setBusy(true);
    setError(null);

    const actionLabel = actionLabels[currentBeat.id];
    const echoUserMessage = currentBeat.action.kind !== "complete";
    if (echoUserMessage) {
      setLines((prev) => [
        ...prev,
        { id: `user-${currentBeat.id}`, role: "user", text: actionLabel },
      ]);
    }

    try {
      if (currentBeat.action.kind === "complete") {
        await onComplete("completed");
        return;
      }

      if (currentBeat.action.kind === "next_section") {
        const next = nextSectionAfter(currentBeat.section);
        if (!next) {
          await onComplete("completed");
          return;
        }
        const response = await onPatchPart2(next);
        const nextSection = response.part2.section ?? next;
        const nextIndex = firstBeatIndexForSection(nextSection);
        const nextBeat = ONBOARDING_PART2_BEATS[nextIndex];
        setSection(nextSection);
        setBeatIndex(nextIndex);
        if (nextBeat) {
          setLines((prev) => [...prev, lineFromBeat(nextBeat, example)]);
        }
        return;
      }

      const nextIndex = beatIndex + 1;
      const nextBeat = ONBOARDING_PART2_BEATS[nextIndex];
      if (!nextBeat) {
        await onComplete("completed");
        return;
      }
      setBeatIndex(nextIndex);
      setSection(nextBeat.section);
      setLines((prev) => [...prev, lineFromBeat(nextBeat, example)]);
    } catch {
      setError(t("onboarding.part2.continueError"));
      if (echoUserMessage) {
        setLines((prev) => prev.filter((line) => line.id !== `user-${currentBeat.id}`));
      }
    } finally {
      setBusy(false);
    }
  }, [actionLabels, beatIndex, busy, currentBeat, example, onComplete, onPatchPart2, starting, t]);

  const handleSkip = useCallback(async () => {
    if (busy || starting) return;
    setBusy(true);
    setError(null);
    try {
      await onComplete("skipped");
    } catch {
      setError(t("onboarding.part2.skipError"));
      setBusy(false);
    }
  }, [busy, onComplete, starting, t]);

  const resolvedActionLabel = currentBeat ? actionLabels[currentBeat.id] : null;

  return (
    <main
      className="absolute inset-0 z-50 flex flex-col bg-background text-foreground"
      aria-label={t("onboarding.part2.ariaLabel")}
    >
      <header className="flex shrink-0 items-center justify-between gap-4 border-b border-border/60 px-5 py-5 sm:px-8">
        <div className="flex min-w-0 items-center gap-3">
          <GenesisIcon className="size-5 shrink-0 text-foreground" aria-hidden />
          <div className="min-w-0">
            <p className="truncate text-sm font-medium">{sectionLabel}</p>
            <p className="text-xs text-muted-foreground">{t("onboarding.part2.intro")}</p>
          </div>
        </div>
        <div className="flex items-center gap-4">
          <SectionDots active={section} />
          <Button
            type="button"
            variant="ghost"
            size="sm"
            disabled={busy || starting}
            onClick={() => void handleSkip()}
            className="text-muted-foreground hover:text-foreground"
          >
            {t("onboarding.part2.skip")}
          </Button>
        </div>
      </header>

      <div ref={scrollerRef} className="min-h-0 flex-1 overflow-y-auto px-5 py-6 sm:px-8">
        <div className="mx-auto flex w-full max-w-5xl flex-col gap-5">
          {lines.map((line) =>
            line.role === "assistant" ? (
              <div key={line.id} className="min-w-0">
                <p className="text-[15px] leading-relaxed text-foreground/90">{line.text}</p>
                {line.demo ? (
                  <OnboardingPart2Demo
                    kind={line.demo}
                    pack={contentPack}
                    teamName={example.name}
                    teamPurpose={example.purpose}
                    className="mt-3"
                  />
                ) : null}
              </div>
            ) : (
              <div key={line.id} className="flex justify-end">
                <div className="max-w-[85%] rounded-sm bg-muted px-3.5 py-2 text-sm text-foreground">
                  {line.text}
                </div>
              </div>
            ),
          )}

          {starting ? (
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <Loader2 className="size-4 animate-spin" aria-hidden />
              {t("onboarding.part2.starting")}
            </div>
          ) : null}
        </div>
      </div>

      <footer className="shrink-0 border-t border-border/60 px-5 py-4 sm:px-8">
        <div className="mx-auto flex w-full max-w-5xl flex-col gap-3">
          {error ? (
            <p className="text-sm text-destructive" role="alert">
              {error}
            </p>
          ) : null}
          {resolvedActionLabel ? (
            <div className="flex justify-end">
              <Button
                type="button"
                size="lg"
                disabled={busy || starting || !currentBeat}
                onClick={() => void handleAction()}
              >
                {busy ? (
                  <>
                    <Loader2 className="size-4 animate-spin" aria-hidden />
                    {t("onboarding.part2.working")}
                  </>
                ) : (
                  resolvedActionLabel
                )}
              </Button>
            </div>
          ) : null}
        </div>
      </footer>
    </main>
