import { cn } from "@web/lib/utils";
import { GenesisIcon } from "./genesis-icon";

export type GenesisLoaderVariant = "default" | "inverse" | "muted";

export function GenesisLoader({
  className,
  label = "Loading",
  variant = "default",
}: {
  className?: string;
  label?: string;
  /** `default`/`inverse` inherit the parent text color (use in buttons). `muted` for standalone loaders. */
  variant?: GenesisLoaderVariant;
}) {
  return (
    <GenesisIcon
      motion="loop"
      className={cn(
        "size-5",
        variant === "muted" ? "text-muted-foreground" : "text-current",
        className,
      )}
      aria-label={label}
    />
  );
}

export function GenesisLoadingState({
  label = "Loading Genesis",
  className,
}: {
  label?: string;
  className?: string;
}) {
  return (
    <div
      className={cn("flex w-full flex-col items-center justify-center gap-4", className)}
      role="status"
    >
      <GenesisLoader variant="muted" className="size-10" label={label} />
      <span className="text-sm font-medium text-muted-foreground">{label}</span>
    </div>
  );
}

