import { cn } from "@web/lib/utils";
import type { OnboardingPart2ContentPack } from "../../../domain/onboarding-v2-content-pack";
import { formatExamplePurpose, type OnboardingPart2DemoKind } from "./onboarding-part2-script";

export type OnboardingPart2DemoProps = {
  kind: OnboardingPart2DemoKind;
  pack: OnboardingPart2ContentPack;
  /** Override pack team name (Part 2 selected example). */
  teamName?: string | null;
  /** Override pack team purpose (Part 2 selected example). */
  teamPurpose?: string | null;
  className?: string;
};

/**
 * Shared Part 2 / product-tour demo chrome.
 * Same markup for onboarding beats and Help/`/tour` specimens.
 */
export function OnboardingPart2Demo({
  kind,
  pack,
  teamName,
  teamPurpose,
  className,
}: OnboardingPart2DemoProps) {
  const name = teamName?.trim() || pack.teamName;
  const purpose = formatExamplePurpose(teamPurpose?.trim() || pack.teamPurpose);

  if (kind === "team") {
    return (
      <div
        className={cn(
          "max-w-md rounded-sm border border-border bg-card p-4 text-left shadow-sm",
          className,
        )}
      >
        <p className="text-sm font-medium text-foreground">{name}</p>
        <p className="mt-1 text-xs text-muted-foreground">{purpose}</p>
        <div className="mt-3 flex flex-wrap gap-2 text-xs text-muted-foreground">
          <span className="rounded-sm border border-border bg-muted/60 px-2 py-1">Playbooks</span>
          <span className="rounded-sm border border-border bg-muted/60 px-2 py-1">Automations</span>
          <span className="rounded-sm border border-border bg-muted/60 px-2 py-1">Improvement</span>
        </div>
      </div>
    );
  }

  if (kind === "playbook") {
    return (
      <div
        className={cn(
          "max-w-md rounded-sm border border-border bg-card p-4 text-left shadow-sm",
          className,
        )}
      >
        <p className="text-sm font-medium text-foreground">{pack.playbook.title}</p>
        <ol className="mt-3 space-y-1.5 text-xs text-muted-foreground">
          {pack.playbook.steps.map((step, index) => (
            <li key={step}>
              {index + 1}. {step}
            </li>
          ))}
        </ol>
      </div>
    );
  }

  if (kind === "automation") {
    return (
      <div
        className={cn(
          "max-w-md rounded-sm border border-border bg-card p-4 text-left shadow-sm",
          className,
        )}
      >
        <p className="text-sm font-medium text-foreground">{pack.automation.scheduleLabel}</p>
        <p className="mt-2 text-xs text-muted-foreground">{pack.automation.runsLine}</p>
      </div>
    );
  }

  if (kind === "attention") {
    return (
      <div className={cn("max-w-md space-y-2 text-left", className)}>
        <div className="rounded-sm border border-border bg-card p-3 shadow-sm">
          <p className="text-sm font-medium text-foreground">Needs you</p>
          <p className="mt-1 text-xs text-muted-foreground">{pack.attention.needsYou}</p>
        </div>
        <div className="rounded-sm border border-border bg-card p-3 shadow-sm">
          <p className="text-sm font-medium text-foreground">Improvement Office</p>
          <p className="mt-1 text-xs text-muted-foreground">{pack.attention.improvement}</p>
        </div>
      </div>
    );
  }

  if (kind === "collection") {
    return (
      <div
        className={cn(
          "max-w-md rounded-sm border border-border bg-card p-4 text-left shadow-sm",
          className,
        )}
      >
        <div className="flex items-center justify-between gap-2">
          <p className="text-sm font-medium text-foreground">{pack.collection.title}</p>
          <span className="text-[10px] text-muted-foreground">{pack.collection.syncLabel}</span>
        </div>
        <ul className="mt-3 space-y-2 text-xs text-muted-foreground">
          {pack.collection.rows.map((row, index) => (
            <li
              key={row.name}
              className={
                index < pack.collection.rows.length - 1
                  ? "flex justify-between gap-3 border-b border-border/50 pb-2"
                  : "flex justify-between gap-3"
              }
            >
              <span className="text-foreground">{row.name}</span>
              <span>{row.status}</span>
            </li>
          ))}
        </ul>
      </div>
    );
  }

  return (
    <div
      className={cn(
        "max-w-lg overflow-hidden rounded-sm border border-border bg-card text-left shadow-sm",
        className,
      )}
    >
      <div className="flex items-center gap-2 border-b border-border bg-muted/40 px-3 py-2">
        <div className="flex gap-1.5" aria-hidden>
          <span className="size-2 rounded-sm bg-foreground/25" />
          <span className="size-2 rounded-sm bg-foreground/25" />
          <span className="size-2 rounded-sm bg-foreground/25" />
        </div>
        <p className="min-w-0 flex-1 truncate rounded-sm border border-border/60 bg-background px-2 py-0.5 text-[11px] text-muted-foreground">
          {pack.app.urlPath}
        </p>
      </div>
      <div className="border-b border-border px-3 py-2">
        <div className="flex items-center justify-between gap-3">
          <div>
            <p className="text-sm font-semibold text-foreground">{pack.app.title}</p>
            <p className="text-[11px] text-muted-foreground">{pack.app.teamLabel || name}</p>
          </div>
          <span className="rounded-sm border border-border bg-background px-2 py-1 text-[11px] font-medium text-foreground">
            {pack.app.primaryAction}
          </span>
        </div>
      </div>
      <div className="grid grid-cols-3 gap-2 border-b border-border px-3 py-3">
        {pack.app.stats.map((stat) => (
          <div key={stat.label} className="rounded-sm border border-border bg-muted/30 px-2 py-2">
            <p className="text-[10px] uppercase tracking-wide text-muted-foreground">
              {stat.label}
            </p>
            <p className="mt-0.5 text-sm font-semibold text-foreground">{stat.value}</p>
          </div>
        ))}
      </div>
      <ul className="space-y-0 text-xs">
        {pack.app.rows.map((row, index) => (
          <li
            key={row.title}
            className={
              index < pack.app.rows.length - 1
                ? "flex items-center justify-between gap-3 border-b border-border/50 px-3 py-2.5"
                : "flex items-center justify-between gap-3 px-3 py-2.5"
            }
          >
            <span>
              <span className="font-medium text-foreground">{row.title}</span>
              <span className="mt-0.5 block text-muted-foreground">{row.subtitle}</span>
            </span>
            <span className="rounded-sm border border-border bg-muted/50 px-1.5 py-0.5 text-[10px] text-foreground">
              {row.value}
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { GenesisIcon } from "@web/components/genesis-icon";
import { TeamBuilderSessionChatPanel } from "@web/components/session-assistant/surfaces/team-builder-feed";
import {
  applyTeamBuilderSessionProposals,
  resetTeamBuilderAssistantSession,
} from "@web/lib/teams/team-builder-api";
import { useTeamBuilderChat } from "@web/lib/teams/use-team-builder-chat";
import { Loader2 } from "lucide-react";
import { useCallback, useEffect, useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import { Button } from "@/components/ui/button";

export type OnboardingPart1Props = {
  resumeBuildSlug: string | null;
  onApplied: (buildSlug: string) => void | Promise<void>;
};

type BootstrapState =
  | { status: "loading" }
  | { status: "ready"; buildSlug: string }
  | { status: "error"; message: string };

export const ONBOARDING_PART1_WELCOME_MESSAGE =
  "Let's set up your first Team. Tell me about the work you want it to own, and I'll put a starting Team together.";

export function OnboardingPart1({ resumeBuildSlug, onApplied }: OnboardingPart1Props) {
  const { t } = useTranslation("onboarding");
  const [bootstrap, setBootstrap] = useState<BootstrapState>({ status: "loading" });
  const bootstrappedRef = useRef(false);

  const bootstrapBuild = useCallback(async () => {
    setBootstrap({ status: "loading" });
    try {
      const resumed = resumeBuildSlug?.trim() || null;
      if (resumed) {
        setBootstrap({ status: "ready", buildSlug: resumed });
        return;
      }
      const session = await resetTeamBuilderAssistantSession({ onboardingPart1: true });
      setBootstrap({ status: "ready", buildSlug: session.slug });
    } catch {
      setBootstrap({
        status: "error",
        message: t("onboarding.part1.bootstrapError"),
      });
    }
  }, [resumeBuildSlug, t]);

  useEffect(() => {
    if (bootstrappedRef.current) return;
    bootstrappedRef.current = true;
    void bootstrapBuild();
  }, [bootstrapBuild]);

  const handleRetryBootstrap = useCallback(() => {
    bootstrappedRef.current = false;
    void bootstrapBuild().finally(() => {
      bootstrappedRef.current = true;
    });
  }, [bootstrapBuild]);

  if (bootstrap.status === "loading") {
    return (
      <div className="absolute inset-0 grid place-items-center bg-background">
        <Loader2
          className="size-6 animate-spin text-muted-foreground"
          aria-label={t("onboarding.part1.loading")}
        />
      </div>
    );
  }

  if (bootstrap.status === "error") {
    return (
      <div className="absolute inset-0 grid place-items-center bg-background px-6">
        <div className="flex max-w-sm flex-col items-center gap-4 text-center">
          <p className="text-base text-muted-foreground">{bootstrap.message}</p>
          <Button type="button" size="lg" onClick={handleRetryBootstrap}>
            {t("onboarding.part1.retry")}
          </Button>
        </div>
      </div>
    );
  }

  return <OnboardingPart1Chat buildSlug={bootstrap.buildSlug} onApplied={onApplied} />;
}

function OnboardingPart1Chat({
  buildSlug,
  onApplied,
}: {
  buildSlug: string;
  onApplied: (buildSlug: string) => void | Promise<void>;
}) {
  const { t } = useTranslation("onboarding");
  const chat = useTeamBuilderChat({
    welcomeMessage: ONBOARDING_PART1_WELCOME_MESSAGE,
    initialBuildSlug: buildSlug,
  });
  const [applyBusy, setApplyBusy] = useState(false);
  const [applyError, setApplyError] = useState<string | null>(null);
  const appliedRef = useRef(false);

  const proposal = chat.proposals[0] ?? null;
  const awaitingApply = Boolean(proposal) || applyBusy;
  const canApply = Boolean(proposal) && !chat.isBusy && !applyBusy && !appliedRef.current;

  const handleApply = useCallback(async () => {
    if (!canApply || appliedRef.current) return;
    const slug = chat.assistantSession?.slug ?? buildSlug;
    setApplyBusy(true);
    setApplyError(null);
    try {
      await applyTeamBuilderSessionProposals(slug, {});
      appliedRef.current = true;
      await onApplied(slug);
    } catch {
      setApplyError(t("onboarding.part1.applyError"));
      setApplyBusy(false);
    }
  }, [buildSlug, canApply, chat, onApplied, t]);

  return (
    <main
      className="absolute inset-0 z-50 flex flex-col bg-background text-foreground"
      aria-label={t("onboarding.part1.ariaLabel")}
    >
      <header className="flex shrink-0 items-center justify-between gap-4 border-b border-border/60 px-5 py-5 sm:px-8">
        <div className="flex min-w-0 items-center gap-3">
          <GenesisIcon className="size-5 shrink-0 text-foreground" aria-hidden />
          <div className="min-w-0">
            <p className="truncate text-sm font-medium">{t("onboarding.part1.title")}</p>
          </div>
        </div>
      </header>

      <div className="mx-auto flex min-h-0 w-full max-w-5xl flex-1 flex-col px-5 sm:px-8">
        <div className="relative flex min-h-0 flex-1 flex-col">
          <TeamBuilderSessionChatPanel
            loading={chat.loading}
            error={chat.error}
            messages={chat.messages}
            thread={chat.thread}
            sessionId={chat.sessionId}
            onSend={chat.sendMessage}
            className="min-h-0 flex-1"
            showHeader={false}
            showAssistantIcon={false}
            composerLocked={applyBusy}
            composerHidden={awaitingApply}
            createPiiSendConsentUi={chat.piiSendConsentUi}
            agentBuilds={chat.agentBuilds}
          />

          {proposal || applyError ? (
            <div className="shrink-0 border-t border-border/60 bg-background py-4">
              <div className="flex w-full flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
                <div className="min-w-0">
                  {proposal ? (
                    <>
                      <p className="text-sm font-medium text-foreground">{proposal.name}</p>
                      <p className="mt-0.5 text-xs text-muted-foreground">
                        {t("onboarding.part1.proposalDescription")}
                      </p>
                    </>
                  ) : null}
                  {applyError ? (
                    <p className="mt-1 text-sm text-destructive">{applyError}</p>
                  ) : null}
                </div>
                <Button
                  type="button"
                  size="lg"
                  disabled={!canApply}
                  onClick={() => void handleApply()}
                  className="shrink-0"
                >
                  {applyBusy ? (
                    <>
                      <Loader2 className="size-4 animate-spin" aria-hidden />
                      {t("onboarding.part1.creating")}
                    </>
                  ) : (
                    t("onboarding.part1.create")
                  )}
                </Button>
              </div>
            </div>
          ) : null}
        </div>
      </div>
    </main>
  );
}

