/** Routes that render outside the authenticated app shell (no sidebar, hub WS, or voice preload). */
export function isPublicShellRoute(pathname = window.location.pathname): boolean {
  return (
    pathname.startsWith("/share/") ||
    pathname === "/desktop-auth-return" ||
    pathname === "/switch-org" ||
    pathname === "/login" ||
    pathname === "/logout"
  );
}

/** Ops control plane paths (`/ops`, `/ops/orgs`, …). */
export function isOpsShellRoute(pathname = window.location.pathname): boolean {
  return pathname === "/ops" || pathname.startsWith("/ops/");
}

/**
 * Unauthenticated App may render these without forcing login.
 * Ops is included only when local ops bootstrap is on (first-org / empty DB).
 */
export function canRenderUnauthenticatedShell(
  localOpsBootstrap: boolean,
  pathname = window.location.pathname,
): boolean {
  if (isPublicShellRoute(pathname)) return true;
  return localOpsBootstrap && isOpsShellRoute(pathname);
}

import { queryFetchJson } from "@web/lib/query-fetch";
import type {
  OnboardingPart2ContentPack,
  OnboardingV2Part2Section,
  OnboardingV2Part2Status,
} from "../../domain/onboarding-v2";

export interface OnboardingV2StateResponse {
  version: 2;
  terminalComplete: boolean;
  currentPhase: "welcome" | "part1" | "part2" | "complete";
  welcome: { complete: boolean };
  part1: { required: boolean; complete: boolean };
  part2: {
    status: OnboardingV2Part2Status;
    section: OnboardingV2Part2Section | null;
  };
  sourcePart1BuildSlug: string | null;
  resumeBuildSlug: string | null;
  selectedExample: {
    name: string;
    purpose: string | null;
    companyContext: string | null;
    source: "part1_blueprint" | "existing_team" | "fallback";
    simulated: true;
    /** Present when currentPhase is part2 (server generate-or-fallback). */
    contentPack?: OnboardingPart2ContentPack;
  };
}

export type OnboardPageView =
  | "loading"
  | "error"
  | "welcome"
  | "part1"
  | "part2"
  | "placeholder"
  | "complete";

export function resolveOnboardPageView(input: {
  isPending: boolean;
  isError: boolean;
  state: OnboardingV2StateResponse | undefined;
}): OnboardPageView {
  if (input.isPending) return "loading";
  if (input.isError || !input.state) return "error";
  if (input.state.terminalComplete || input.state.currentPhase === "complete") return "complete";
  if (input.state.currentPhase === "welcome") return "welcome";
  if (input.state.currentPhase === "part1") return "part1";
  if (input.state.currentPhase === "part2") return "part2";
  return "placeholder";
}

export function onboardingV2PlaceholderCopy(
  phase: OnboardingV2StateResponse["currentPhase"],
): string {
  if (phase === "part2") return "Next: a short tour of Genesis";
  return "Next: set up your company";
}

export async function fetchOnboardingV2State(): Promise<OnboardingV2StateResponse> {
  return queryFetchJson<OnboardingV2StateResponse>("/api/users/me/onboarding-state");
}

import { useQueryClient } from "@tanstack/react-query";
import { useNavigate } from "@tanstack/react-router";
import { OnboardingPart1 } from "@web/components/onboarding/onboarding-part1";
import { OnboardingPart2 } from "@web/components/onboarding/onboarding-part2";
import { OnboardingWelcome } from "@web/components/onboarding/onboarding-welcome";
import { useOnboardingV2State } from "@web/hooks/use-onboarding-v2-state";
import { useSession } from "@web/lib/auth";
import { writeCachedOnboarded } from "@web/lib/onboard-status";
import {
  type OnboardingV2StateResponse,
  onboardingV2PlaceholderCopy,
  resolveOnboardPageView,
} from "@web/lib/onboarding-v2-client";
import { dismissProductTour } from "@web/lib/product-tour-status";
import { queryKeys } from "@web/lib/query-keys";
import { patchJson, postJson } from "@web/lib/query-mutations";
import { Loader2 } from "lucide-react";
import { useCallback, useEffect, useState } from "react";
import { useTranslation } from "react-i18next";
import { Button } from "@/components/ui/button";
import type { OnboardingV2Part2Section } from "../../domain/onboarding-v2";

export function Onboard() {
  const { t } = useTranslation("onboarding");
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const { user } = useSession();
  const stateQuery = useOnboardingV2State();
  const [welcomeBusy, setWelcomeBusy] = useState(false);
  const [welcomeError, setWelcomeError] = useState<string | null>(null);

  const view = resolveOnboardPageView({
    isPending: stateQuery.isPending,
    isError: stateQuery.isError,
    state: stateQuery.data,
  });

  useEffect(() => {
    if (view !== "complete") return;
    navigate({ to: "/", replace: true });
  }, [navigate, view]);

  const handleGetStarted = useCallback(async () => {
    if (welcomeBusy) return;
    setWelcomeBusy(true);
    setWelcomeError(null);
    try {
      const next = await patchJson<OnboardingV2StateResponse>("/api/users/me/onboarding-state", {
        welcomeCompleted: true,
      });
      queryClient.setQueryData(queryKeys.auth.onboardingState(), next);
    } catch {
      setWelcomeError(t("onboarding.page.continueError"));
    } finally {
      setWelcomeBusy(false);
    }
  }, [queryClient, t, welcomeBusy]);

  const handlePatchPart2 = useCallback(
    async (section: OnboardingV2Part2Section) => {
      const next = await patchJson<OnboardingV2StateResponse>("/api/users/me/onboarding-state", {
        part2: { status: "in_progress", section },
      });
      queryClient.setQueryData(queryKeys.auth.onboardingState(), next);
      return next;
    },
    [queryClient],
  );

  const handlePart1Applied = useCallback(
    async (buildSlug: string) => {
      const next = await patchJson<OnboardingV2StateResponse>("/api/users/me/onboarding-state", {
        sourcePart1BuildSlug: buildSlug,
      });
      queryClient.setQueryData(queryKeys.auth.onboardingState(), next);
    },
    [queryClient],
  );

  const handlePart2Complete = useCallback(
    async (outcome: "completed" | "skipped") => {
      const next = await postJson<OnboardingV2StateResponse>("/api/users/me/onboarding-complete", {
        outcome,
      });
      queryClient.setQueryData(queryKeys.auth.onboardingState(), next);
      // Always clear the React Query flag so BriefingGate cannot see stale false
      // when session user is momentarily unavailable; localStorage stays per-user.
      queryClient.setQueryData(queryKeys.auth.onboardStatus(), true);
      if (user?.id) writeCachedOnboarded(user.id);
      dismissProductTour();
      return next;
    },
    [queryClient, user?.id],
  );

  if (view === "loading" || view === "complete") {
    return (
      <div className="fixed inset-0 z-50 grid place-items-center bg-[#090b14]">
        <Loader2
          className="size-6 animate-spin text-white/70"
          aria-label={t("onboarding.page.loading")}
        />
      </div>
    );
  }

  if (view === "error") {
    return (
      <div className="fixed inset-0 z-50 grid place-items-center bg-[#090b14] px-6">
        <div className="flex max-w-sm flex-col items-center gap-4 text-center">
          <p className="text-base text-white/80">{t("onboarding.page.loadError")}</p>
          <Button
            type="button"
            size="lg"
            onClick={() => void stateQuery.refetch()}
            className="bg-white text-[#090b14] hover:bg-white/90"
          >
            {t("onboarding.page.retry")}
          </Button>
        </div>
      </div>
    );
  }

  if (view === "welcome") {
    return (
      <div className="fixed inset-0 z-50">
        <OnboardingWelcome onGetStarted={() => void handleGetStarted()} busy={welcomeBusy} />
        {welcomeError ? (
          <p
            className="pointer-events-none absolute bottom-8 left-1/2 z-50 -translate-x-1/2 text-sm text-white/70"
            role="status"
          >
            {welcomeError}
          </p>
        ) : null}
      </div>
    );
  }

  if (view === "part1" && stateQuery.data) {
    return (
      <div className="fixed inset-0 z-50">
        <OnboardingPart1
          resumeBuildSlug={stateQuery.data.resumeBuildSlug}
          onApplied={handlePart1Applied}
        />
      </div>
    );
  }

  if (view === "part2" && stateQuery.data) {
    return (
      <div className="fixed inset-0 z-50">
        <OnboardingPart2
          state={stateQuery.data}
          onPatchPart2={handlePatchPart2}
          onComplete={handlePart2Complete}
        />
      </div>
    );
  }

  const phase = stateQuery.data?.currentPhase ?? "part1";
  return (
    <div className="fixed inset-0 z-50 grid place-items-center bg-[#090b14] px-6">
      <p className="text-center text-lg text-white/80">{onboardingV2PlaceholderCopy(phase)}</p>
    </div>
  );
}

