 * Resolve the browser page origin for WebAuthn RP ID / expectedOrigin.
 *
 * Prefer Origin (always sent on credentialed API posts from the page), then
 * Referer, then X-Forwarded-Host (Vite/dev proxy), then fallback. When several
 * candidates exist, prefer a domain name over an IP so proxied local dev
 * (page on localhost, API on 127.0.0.1) still gets rpId "localhost".
 */
export function resolveWebauthnAppBaseUrl(input: {
  originHeader?: string | null;
  refererHeader?: string | null;
  forwardedHostHeader?: string | null;
  forwardedProtoHeader?: string | null;
  fallbackBaseUrl: string;
