        }
      })(),
    ),
    tryParseOrigin(fallbackOrigin),
  ].filter((value): value is string => Boolean(value));

  if (candidates.length === 0) return fallbackOrigin;

  let best = candidates[0]!;
  let bestScore = originScore(best);
  for (const candidate of candidates.slice(1)) {
    const score = originScore(candidate);
    if (score > bestScore) {
      best = candidate;
      bestScore = score;
    }
  }
  return best;
}

