import { describe, expect, it } from "vitest";
import { authenticatedLoginNavigation, authenticatedLoginRedirect } from "./login";

describe("authenticatedLoginNavigation", () => {
  it("defaults to home", () => {
    expect(authenticatedLoginNavigation(undefined)).toEqual({
      kind: "router",
      href: "/",
    });
    expect(authenticatedLoginNavigation("")).toEqual({
      kind: "router",
      href: "/",
    });
    expect(authenticatedLoginNavigation("https://evil.example")).toEqual({
      kind: "router",
      href: "/",
    });
  });

  it("keeps same-app returnTo", () => {
    expect(authenticatedLoginNavigation("/teams")).toEqual({
      kind: "router",
      href: "/teams",
    });
    expect(authenticatedLoginNavigation("/files?view=recent")).toEqual({
      kind: "router",
      href: "/files?view=recent",
    });
  });

  it.each([
    ["edge", "https://pr-1222-edge.agentcompany.com/", "edge.agentcompany.com"],
    ["stable", "https://pr-1222-stable.agentcompany.com/", "app.agentcompany.com"],
  ])("uses document navigation for an allowlisted %s preview returnTo", (_, returnTo, host) => {
    expect(authenticatedLoginNavigation(returnTo, host)).toEqual({
      kind: "document",
      href: `/api/auth/access-handoff?returnTo=${encodeURIComponent(returnTo)}`,
    });
  });

  it.each([
    ["edge", "https://pr-1222-edge.agentcompany.com/", "edge.agentcompany.com"],
    ["stable", "https://pr-1222-stable.agentcompany.com/", "app.agentcompany.com"],
  ])("reloads the document for an allowlisted %s preview returnTo", (_, returnTo, host) => {
    const navigation = authenticatedLoginNavigation(returnTo, host);
    if (navigation === null) throw new Error("expected preview handoff navigation");

    expect(authenticatedLoginRedirect(navigation).options).toMatchObject({
      href: `/api/auth/access-handoff?returnTo=${encodeURIComponent(returnTo)}`,
      reloadDocument: true,
      replace: true,
    });
  });

  it("keeps an explicit account switch on the login page", () => {
    expect(
      authenticatedLoginNavigation(
        "https://pr-1222-edge.agentcompany.com/",
        "edge.agentcompany.com",
        true,
      ),
    ).toBeNull();
  });

  it("keeps same-host absolute returnTo", () => {
    expect(
      authenticatedLoginNavigation(
        "https://edge.agentcompany.com/settings",
        "edge.agentcompany.com",
      ),
    ).toEqual({
      kind: "document",
      href: "https://edge.agentcompany.com/settings",
    });
  });

  it("breaks /login loops", () => {
    expect(authenticatedLoginNavigation("/login")).toEqual({
      kind: "router",
      href: "/",
    });
    expect(authenticatedLoginNavigation("/login?returnTo=%2Fteams")).toEqual({
      kind: "router",
      href: "/",
    });
    expect(
      authenticatedLoginNavigation("https://pr-1222-edge.agentcompany.com/login?returnTo=%2Fteams"),
    ).toEqual({ kind: "router", href: "/" });
  });
});

