import { login } from "@web/lib/auth";
import { renderToStaticMarkup } from "react-dom/server";
import { afterEach, describe, expect, test } from "vitest";
import {
  resolveSessionBootstrapGate,
  SESSION_BOOTSTRAP_WAIT_MS,
  SessionBootstrapUnavailableState,
  scheduleSessionBootstrapWait,
} from "./App";

const originalWindow = globalThis.window;

afterEach(() => {
  globalThis.window = originalWindow;
});

describe("session bootstrap wait", () => {
  test("renders the existing auth failure affordance when the cap elapses", () => {
    const fakeTimer: { elapsed: () => void; scheduledFor: number } = {
      elapsed: () => undefined,
      scheduledFor: -1,
    };

    globalThis.window = {
      setTimeout: (callback: TimerHandler, timeout?: number) => {
        fakeTimer.elapsed = callback as () => void;
        fakeTimer.scheduledFor = timeout ?? 0;
        return 1;
      },
      clearTimeout: () => undefined,
    } as unknown as Window & typeof globalThis;

    let waitExpired = false;
    scheduleSessionBootstrapWait(() => {
      waitExpired = true;
    });

    expect(fakeTimer.scheduledFor).toBe(SESSION_BOOTSTRAP_WAIT_MS);
    fakeTimer.elapsed();
    expect(resolveSessionBootstrapGate({ waiting: true, waitExpired })).toBe("unavailable");

    const html = renderToStaticMarkup(<SessionBootstrapUnavailableState />);
    expect(html).toContain("Sign-in failed");
    expect(html).toContain("Genesis sign-in is temporarily unavailable");
    expect(html).toContain("Try again");
  });

  test("success within the budget proceeds normally", () => {
    let timerCleared = false;
    globalThis.window = {
      setTimeout: () => 1,
      clearTimeout: () => {
        timerCleared = true;
      },
    } as unknown as Window & typeof globalThis;

    const cancelWait = scheduleSessionBootstrapWait(() => undefined);
    cancelWait();

    expect(timerCleared).toBe(true);
    expect(resolveSessionBootstrapGate({ waiting: false, waitExpired: false })).toBeNull();
  });

  test("a definitive unauthenticated response proceeds to the unchanged redirect path", () => {
    const redirect: { url: string | URL | null } = { url: null };
    globalThis.window = {
      location: {
        origin: "http://localhost",
        pathname: "/files",
        search: "?view=recent",
        replace: (url: string | URL) => {
          redirect.url = url;
        },
      },
    } as unknown as Window & typeof globalThis;

    expect(resolveSessionBootstrapGate({ waiting: false, waitExpired: false })).toBeNull();
    login();
    // Web cold-start uses Genesis /login (not the legacy /api/auth/login route).
    expect(String(redirect.url)).toBe("http://localhost/login?returnTo=%2Ffiles%3Fview%3Drecent");
  });
});

