/**
 * WebAuthn / passkey host rules.
 *
 * Browsers require a domain-name RP ID. IP addresses (including 127.0.0.1) are
 * not valid. The only local HTTP exception is the hostname `localhost`.
 *
 * Genesis defaults to http://127.0.0.1:3500 for cookies; passkeys need
 * http://localhost:3500 (same process, different host string).
 *
 * Dev note: Vite proxies /api to 127.0.0.1:3501 with changeOrigin, so the
 * backend request URL host is often 127.0.0.1 even when the page is on
 * localhost. Always prefer Origin / X-Forwarded-Host for WebAuthn RP config.
 */

/** True when hostname is an IP literal (v4 / v6), not a domain name. */
export function isIpHostname(hostname: string): boolean {
  const host = hostname
    .trim()
    .toLowerCase()
    .replace(/^\[|\]$/g, "");
  if (!host) return false;
  // IPv4
  if (/^\d{1,3}(\.\d{1,3}){3}$/.test(host)) return true;
  // IPv6
  if (host.includes(":")) return true;
  return false;
}

/** Hostnames where WebAuthn may run over http (browser secure-context exception). */
export function isWebauthnLocalHttpHost(hostname: string): boolean {
  return hostname.trim().toLowerCase() === "localhost";
}

export type WebauthnHostSupport =
  | { supported: true }
  | {
      supported: false;
      /** Machine-readable reason. */
      reason: "ip_hostname" | "insecure_origin";
      /** User-facing explanation. */
      message: string;
      /** Suggested same-path URL on localhost when current host is loopback IP. */
      localhostUrl?: string;
    };

/**
 * Whether the current browser location can run WebAuthn ceremonies.
 * Call only in the browser (uses window.location).
 */
export function getBrowserWebauthnHostSupport(
  locationLike: Pick<
    Location,
    "protocol" | "hostname" | "port" | "pathname" | "search" | "hash"
  > = typeof window !== "undefined"
    ? window.location
    : ({
        protocol: "http:",
        hostname: "127.0.0.1",
        port: "3500",
        pathname: "/",
        search: "",
        hash: "",
      } as Location),
): WebauthnHostSupport {
  const { protocol, hostname } = locationLike;
  const isSecure = protocol === "https:" || isWebauthnLocalHttpHost(hostname);

  if (isIpHostname(hostname)) {
    const localhostUrl = buildLocalhostUrl(locationLike);
    return {
      supported: false,
      reason: "ip_hostname",
      message:
        "Passkeys can’t run on 127.0.0.1 (browsers require a domain name). Open Genesis at localhost, sign in again if needed, then set up your passkey.",
      localhostUrl,
    };
  }

  if (!isSecure) {
    return {
      supported: false,
      reason: "insecure_origin",
      message: "Passkeys require a secure connection (HTTPS) or localhost.",
    };
  }

  return { supported: true };
}

/** Server-side check from an absolute app base URL (e.g. getAppBaseUrl). */
export function getWebauthnHostSupportFromBaseUrl(appBaseUrl: string): WebauthnHostSupport {
  let url: URL;
  try {
    url = new URL(appBaseUrl);
  } catch {
    return {
      supported: false,
      reason: "insecure_origin",
      message: "Passkeys could not determine this site’s address.",
    };
  }
  return getBrowserWebauthnHostSupport({
    protocol: url.protocol,
    hostname: url.hostname,
    port: url.port,
    pathname: "/",
    search: "",
    hash: "",
  });
}

