import { describe, expect, it } from "vitest";
import { authenticatedLoginNavigation, authenticatedLoginRedirect } from "./login";

describe("authenticatedLoginNavigation", () => {
  it("defaults to home", () => {
    expect(authenticatedLoginNavigation(undefined)).toEqual({
      kind: "router",
      href: "/",
    });
    expect(authenticatedLoginNavigation("")).toEqual({
      kind: "router",
      href: "/",
    });
    expect(authenticatedLoginNavigation("https://evil.example")).toEqual({
      kind: "router",
      href: "/",
    });
  });

  it("keeps same-app returnTo", () => {
    expect(authenticatedLoginNavigation("/teams")).toEqual({
      kind: "router",
      href: "/teams",
    });
    expect(authenticatedLoginNavigation("/files?view=recent")).toEqual({
      kind: "router",
      href: "/files?view=recent",
    });
  });

  it.each([
    ["edge", "https://pr-1222-edge.agentcompany.com/", "edge.agentcompany.com"],
    ["stable", "https://pr-1222-stable.agentcompany.com/", "app.agentcompany.com"],
  ])("uses document navigation for an allowlisted %s preview returnTo", (_, returnTo, host) => {
    expect(authenticatedLoginNavigation(returnTo, host)).toEqual({
      kind: "document",
      href: `/api/auth/access-handoff?returnTo=${encodeURIComponent(returnTo)}`,
    });
  });

  it.each([
    ["edge", "https://pr-1222-edge.agentcompany.com/", "edge.agentcompany.com"],
    ["stable", "https://pr-1222-stable.agentcompany.com/", "app.agentcompany.com"],
  ])("reloads the document for an allowlisted %s preview returnTo", (_, returnTo, host) => {
    const navigation = authenticatedLoginNavigation(returnTo, host);
    if (navigation === null) throw new Error("expected preview handoff navigation");

    expect(authenticatedLoginRedirect(navigation).options).toMatchObject({
      href: `/api/auth/access-handoff?returnTo=${encodeURIComponent(returnTo)}`,
      reloadDocument: true,
      replace: true,
    });
  });

  it("keeps an explicit account switch on the login page", () => {
    expect(
      authenticatedLoginNavigation(
        "https://pr-1222-edge.agentcompany.com/",
        "edge.agentcompany.com",
        true,
      ),
    ).toBeNull();
  });

  it("keeps same-host absolute returnTo", () => {
    expect(
      authenticatedLoginNavigation(
        "https://edge.agentcompany.com/settings",
        "edge.agentcompany.com",
      ),
    ).toEqual({
      kind: "document",
      href: "https://edge.agentcompany.com/settings",
    });
  });

  it("breaks /login loops", () => {
    expect(authenticatedLoginNavigation("/login")).toEqual({
      kind: "router",
      href: "/",
    });
    expect(authenticatedLoginNavigation("/login?returnTo=%2Fteams")).toEqual({
      kind: "router",
      href: "/",
    });
    expect(
      authenticatedLoginNavigation("https://pr-1222-edge.agentcompany.com/login?returnTo=%2Fteams"),
    ).toEqual({ kind: "router", href: "/" });
  });
});

import { LOGIN_CODE_LENGTH } from "@lib/login-code";

type AuthTranslation = (
  key:
    | "auth.errors.couldNotComplete"
    | "auth.errors.googleAccessNeedsApproval"
    | "auth.errors.googleAccessTitle"
    | "auth.errors.googleSignInTitle"
    | "auth.errors.googleUnavailableTitle",
) => string;

export type AuthCallbackNotice = {
  code: string;
  title: string;
  description: string;
};

const RETRYABLE_AUTH_CODES = new Set(["auth_failed", "auth_unavailable", "consent_required"]);

export function isRetryableAuthCallbackError(code: string): boolean {
  return RETRYABLE_AUTH_CODES.has(code.trim());
}

/** Titles only. Broker `error_description` owns the body copy. */
export function authCallbackNoticeTitle(
  code: string,
  signedIn: boolean,
  t: AuthTranslation,
): string {
  switch (code.trim()) {
    case "consent_required":
      return t("auth.errors.googleAccessNeedsApproval");
    case "auth_unavailable":
      return t("auth.errors.googleUnavailableTitle");
    default:
      return signedIn ? t("auth.errors.googleAccessTitle") : t("auth.errors.googleSignInTitle");
  }
}

export function readAuthCallbackNotice(
  search: string,
  signedIn: boolean,
  t: AuthTranslation,
): AuthCallbackNotice | null {
  const params = new URLSearchParams(search.startsWith("?") ? search.slice(1) : search);
  const code = params.get("error")?.trim();
  if (!code) return null;
  return {
    code,
    title: authCallbackNoticeTitle(code, signedIn, t),
    description: params.get("error_description")?.trim() || t("auth.errors.couldNotComplete"),
  };
}

export function readLoginError(t: AuthTranslation): string | null {
  return readAuthCallbackNotice(window.location.search, false, t)?.description ?? null;
}

export function normalizeEmail(value: string): string {
  return value.trim().toLowerCase();
}

export function formatCountdown(totalSeconds: number): string {
  const s = Math.max(0, Math.floor(totalSeconds));
  const m = Math.floor(s / 60);
  const r = s % 60;
  return `${m}:${r.toString().padStart(2, "0")}`;
}

/** Straight to Catalyst Google — email is optional account preselect only. */
export function googleHref(returnTo: string, email?: string): string {
  const params = new URLSearchParams();
  if (returnTo && returnTo !== "/") params.set("returnTo", returnTo);
  const hint = email ? normalizeEmail(email) : "";
  if (hint.includes("@")) params.set("login_hint", hint);
  const qs = params.toString();
  return qs ? `/api/auth/google?${qs}` : "/api/auth/google";
}

