import { cn } from "@web/lib/utils";
import type { OnboardingPart2ContentPack } from "../../../domain/onboarding-v2-content-pack";
import { formatExamplePurpose, type OnboardingPart2DemoKind } from "./onboarding-part2-script";

export type OnboardingPart2DemoProps = {
  kind: OnboardingPart2DemoKind;
  pack: OnboardingPart2ContentPack;
  /** Override pack team name (Part 2 selected example). */
  teamName?: string | null;
  /** Override pack team purpose (Part 2 selected example). */
  teamPurpose?: string | null;
  className?: string;
};

/**
 * Shared Part 2 / product-tour demo chrome.
 * Same markup for onboarding beats and Help/`/tour` specimens.
 */
export function OnboardingPart2Demo({
  kind,
  pack,
  teamName,
  teamPurpose,
  className,
}: OnboardingPart2DemoProps) {
  const name = teamName?.trim() || pack.teamName;
  const purpose = formatExamplePurpose(teamPurpose?.trim() || pack.teamPurpose);

  if (kind === "team") {
    return (
      <div
        className={cn(
          "max-w-md rounded-sm border border-border bg-card p-4 text-left shadow-sm",
          className,
        )}
      >
        <p className="text-sm font-medium text-foreground">{name}</p>
        <p className="mt-1 text-xs text-muted-foreground">{purpose}</p>
        <div className="mt-3 flex flex-wrap gap-2 text-xs text-muted-foreground">
          <span className="rounded-sm border border-border bg-muted/60 px-2 py-1">Playbooks</span>
          <span className="rounded-sm border border-border bg-muted/60 px-2 py-1">Automations</span>
          <span className="rounded-sm border border-border bg-muted/60 px-2 py-1">Improvement</span>
        </div>
      </div>
    );
  }

  if (kind === "playbook") {
    return (
      <div
        className={cn(
          "max-w-md rounded-sm border border-border bg-card p-4 text-left shadow-sm",
          className,
        )}
      >
        <p className="text-sm font-medium text-foreground">{pack.playbook.title}</p>
        <ol className="mt-3 space-y-1.5 text-xs text-muted-foreground">
          {pack.playbook.steps.map((step, index) => (
            <li key={step}>
              {index + 1}. {step}
            </li>
          ))}
        </ol>
      </div>
    );
  }

  if (kind === "automation") {
    return (
      <div
        className={cn(
          "max-w-md rounded-sm border border-border bg-card p-4 text-left shadow-sm",
          className,
        )}
      >
        <p className="text-sm font-medium text-foreground">{pack.automation.scheduleLabel}</p>
        <p className="mt-2 text-xs text-muted-foreground">{pack.automation.runsLine}</p>
      </div>
    );
  }

  if (kind === "attention") {
    return (
      <div className={cn("max-w-md space-y-2 text-left", className)}>
