import { describe, expect, test } from "vitest";
import {
  authCallbackNoticeTitle,
  isRetryableAuthCallbackError,
  readAuthCallbackNotice,
} from "./login-utils";

const t = (key: string): string => {
  const translations: Record<string, string> = {
    "auth.errors.couldNotComplete": "Sign-in could not be completed. Please try again.",
    "auth.errors.googleAccessNeedsApproval": "Google access needs approval",
    "auth.errors.googleAccessTitle": "Couldn't update Google access",
    "auth.errors.googleSignInTitle": "Couldn't complete Google sign-in",
    "auth.errors.googleUnavailableTitle": "Google is temporarily unavailable",
  };
  return translations[key] ?? key;
};

describe("auth callback copy", () => {
  test("prefers the broker description when present", () => {
    const notice = readAuthCallbackNotice(
      "?error=auth_failed&error_description=Google+could+not+confirm+this+approval.",
      false,
      t,
    );
    expect(notice?.description).toBe("Google could not confirm this approval.");
  });

  test("uses a generic body when the broker omitted a description", () => {
    expect(readAuthCallbackNotice("?error=consent_required", true, t)?.description).toBe(
      "Sign-in could not be completed. Please try again.",
    );
  });

  test("uses update-access title when signed in", () => {
    const notice = readAuthCallbackNotice(
      "?error=auth_failed&error_description=Google+could+not+confirm+this+sign-in.+Please+try+again.",
      true,
      t,
    );
    expect(notice).toEqual({
      code: "auth_failed",
      title: "Couldn't update Google access",
      description: "Google could not confirm this sign-in. Please try again.",
    });
  });

  test("uses sign-in title when signed out", () => {
    expect(authCallbackNoticeTitle("auth_failed", false, t)).toBe(
      "Couldn't complete Google sign-in",
    );
  });

  test("access_denied uses the same signed-in and signed-out titles as the default", () => {
    expect(authCallbackNoticeTitle("access_denied", true, t)).toBe("Couldn't update Google access");
    expect(authCallbackNoticeTitle("access_denied", false, t)).toBe(
      "Couldn't complete Google sign-in",
    );
    expect(
      readAuthCallbackNotice(
        "?error=access_denied&error_description=This+Google+account+is+not+enrolled+for+Genesis+yet.",
        false,
        t,
      )?.description,
    ).toBe("This Google account is not enrolled for Genesis yet.");
  });

  test("only consent and transient failures are retryable", () => {
    expect(isRetryableAuthCallbackError("auth_failed")).toBe(true);
    expect(isRetryableAuthCallbackError("consent_required")).toBe(true);
    expect(isRetryableAuthCallbackError("access_denied")).toBe(false);
  });
});

