it("renders Brazilian Portuguese automation labels, plurals, and preserved values", async () => {
  const i18n = createInstance();
  await i18n.init({
    lng: "pt-BR",
    fallbackLng: "en",
    resources: {
      en: { settings: enSettings },
      "pt-BR": { settings: ptBRSettings },
    },
  });

  expect(i18n.t("settings:automations.actions.runNow")).toBe("Executar agora");
  expect(i18n.t("settings:automations.schedule.everyHours", { count: 1 })).toBe("A cada 1 hora");
  expect(i18n.t("settings:automations.schedule.everyHours", { count: 2 })).toBe("A cada 2 horas");
  expect(i18n.t("settings:automations.schedule.event", { event: "github:pull_request" })).toBe(
    "No evento github:pull_request",
  );
  expect(i18n.t("settings:automations.delete.description", { title: "Morning report" })).toBe(
    "Isso remove Morning report permanentemente. As programações em execução param imediatamente.",
  );
});

