import ptBRSettings from "./locales/pt-BR/settings.json";
import ptBRShell from "./locales/pt-BR/shell.json";
import "./types";

export {
  DEFAULT_LOCALE,
  isSupportedLocale,
  LOCALE_STORAGE_SUFFIX,
  normalizeLocale,
  SUPPORTED_LOCALES,
  type SupportedLocale,
} from "./locales";

const resources = {
  en: {
    capabilities: enCapabilities,
    common: enCommon,
    onboarding: enOnboarding,
    sessions: enSessions,
    settings: enSettings,
    shell: enShell,
  },
  "pt-BR": {
    capabilities: ptBRCapabilities,
    common: ptBRCommon,
    onboarding: ptBROnboarding,
    sessions: ptBRSessions,
    settings: ptBRSettings,
    shell: ptBRShell,
  },
} as const;

function applyDocumentLang(locale: string): void {
  if (typeof document === "undefined") return;
  document.documentElement.lang = normalizeLocale(locale);
}

const genesisLocaleDetector = {
  name: "genesisLocalStorage",
  lookup(): string | undefined {
    const stored = readGenesisLocalStorageItem(LOCALE_STORAGE_SUFFIX);
    return stored ?? undefined;
  },
  cacheUserLanguage(lng: string): void {
    writeGenesisLocalStorageItem(LOCALE_STORAGE_SUFFIX, normalizeLocale(lng));
  },
};

const languageDetector = new LanguageDetector();
languageDetector.addDetector(genesisLocaleDetector);

void i18n
  .use(languageDetector)
  .use(initReactI18next)
  .init({
    resources,
    supportedLngs: [...SUPPORTED_LOCALES],
    fallbackLng: DEFAULT_LOCALE,
    defaultNS: "common",
