import { describe, expect, it } from "vitest";
import { DEFAULT_LOCALE, isSupportedLocale, normalizeLocale } from "./locales";
import enCommon from "./locales/en/common.json";
import enOnboarding from "./locales/en/onboarding.json";
import enSessions from "./locales/en/sessions.json";
import enSettings from "./locales/en/settings.json";
import enShell from "./locales/en/shell.json";
import ptBRCommon from "./locales/pt-BR/common.json";
import ptBROnboarding from "./locales/pt-BR/onboarding.json";
import ptBRSessions from "./locales/pt-BR/sessions.json";
import ptBRSettings from "./locales/pt-BR/settings.json";
import ptBRShell from "./locales/pt-BR/shell.json";

function leafTranslations(value: unknown, prefix = ""): Map<string, string> {
  if (typeof value === "string") return new Map([[prefix, value]]);
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error(`Invalid translation value at ${prefix || "<root>"}`);
  }
  const entries = new Map<string, string>();
  for (const [key, child] of Object.entries(value)) {
    const childPrefix = prefix ? `${prefix}.${key}` : key;
    for (const [childKey, childValue] of leafTranslations(child, childPrefix)) {
      entries.set(childKey, childValue);
    }
  }
  return entries;
}

function interpolationNames(value: string): string[] {
  return [...value.matchAll(/\{\{\s*([^},\s]+)[^}]*\}\}/g)]
    .map((match) => match[1])
    .filter((name): name is string => Boolean(name))
    .sort();
}

function expectResourceParity(englishResource: unknown, portugueseResource: unknown): void {
  const english = leafTranslations(englishResource);
  const portuguese = leafTranslations(portugueseResource);
  expect([...portuguese.keys()].sort()).toEqual([...english.keys()].sort());
  for (const [key, englishValue] of english) {
    expect(interpolationNames(portuguese.get(key) ?? "")).toEqual(interpolationNames(englishValue));
  }
}

describe("normalizeLocale", () => {
  it("keeps supported locales", () => {
    expect(normalizeLocale("en")).toBe("en");
    expect(normalizeLocale("pt-BR")).toBe("pt-BR");
  });

  it("maps Portuguese browser codes to pt-BR", () => {
    expect(normalizeLocale("pt")).toBe("pt-BR");
    expect(normalizeLocale("pt-PT")).toBe("pt-BR");
  });

  it("maps English variants to en", () => {
    expect(normalizeLocale("en-US")).toBe("en");
    expect(normalizeLocale("en-GB")).toBe("en");
  });

  it("falls back to the default locale", () => {
    expect(normalizeLocale(null)).toBe(DEFAULT_LOCALE);
    expect(normalizeLocale("fr")).toBe(DEFAULT_LOCALE);
    expect(isSupportedLocale("fr")).toBe(false);
  });
});

describe("locale resources", () => {
  it("keeps pt-BR resource keys and interpolation placeholders in parity with English", () => {
    expectResourceParity(enCommon, ptBRCommon);
    expectResourceParity(enOnboarding, ptBROnboarding);
    expectResourceParity(enSessions, ptBRSessions);
    expectResourceParity(enSettings, ptBRSettings);
