    expect(normalizeLocale("en")).toBe("en");
    expect(normalizeLocale("pt-BR")).toBe("pt-BR");
  });

  it("maps Portuguese browser codes to pt-BR", () => {
    expect(normalizeLocale("pt")).toBe("pt-BR");
    expect(normalizeLocale("pt-PT")).toBe("pt-BR");
  });

